insert into public.recipes (id, name, description, meal_type, main, emoji, prep_time_min, difficulty, calories, protein_g, carbs_g, fat_g, fiber_g, sugar_g, sodium_mg, ingredients, seasonings, instructions, appliances, keywords, dietary_tags, sort) values
  ('d-chicken-shawarma-plate', 'Chicken Shawarma Plate', 'Spiced chicken with rice, chickpeas, garlic yogurt, cucumber and tomato', 'dinner', 'chicken', '🍗', 30, 'balanced', 829, 59, 98, 21, 8, 9, 309, '[{"name":"chicken","amount":180,"unit":"g"},{"name":"rice","amount":90,"unit":"g"},{"name":"chickpeas","amount":80,"unit":"g"},{"name":"greek yogurt","amount":60,"unit":"g"},{"name":"cucumber","amount":80,"unit":"g"},{"name":"tomato","amount":80,"unit":"g"},{"name":"olive oil","amount":10,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1 tsp paprika","1/2 tsp chili flakes","1/2 tsp ground coriander","salt"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes, adding the drained chickpeas for the last minute, then drain","Slice the chicken thinly and coat it with the cumin, paprika, chili flakes, coriander and salt","Fry in the olive oil over high heat for 6 to 7 minutes until browned at the edges","Serve over the rice and chickpeas with the diced cucumber and tomato and the yogurt"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","spicy","hearty","chicken","rice","chickpeas","greek yogurt","cucumber","tomato","olive oil","stovetop","dinner"]'::jsonb, '["gluten-free","nut-allergy","halal"]'::jsonb, 150),
  ('d-tofu-lentil-bolognese', 'Tofu and Lentil Bolognese', 'Pasta with a rich tomato sauce of lentils and crumbled tofu', 'dinner', 'lentils', '🍝', 35, 'balanced', 859, 61, 103, 27, 19, 10, 269, '[{"name":"lentils","amount":70,"unit":"g"},{"name":"tofu","amount":200,"unit":"g"},{"name":"pasta","amount":50,"unit":"g"},{"name":"chopped tomatoes","amount":200,"unit":"g"},{"name":"onion","amount":60,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"},{"name":"olive oil","amount":8,"unit":"g"}]'::jsonb, '["1 tsp dried oregano","pinch of salt","black pepper"]'::jsonb, '["Dice the onion, crush the garlic and soften both in the olive oil in a deep pan over medium heat for 4 minutes","Crumble in the tofu and fry for 5 minutes until it starts to colour","Add the rinsed lentils, the chopped tomatoes, the oregano and {350} ml of water, and simmer for 20 minutes until the lentils are tender and the sauce is thick","Meanwhile cook the pasta in salted boiling water until al dente and drain it","Season the sauce with salt and black pepper and serve it over the pasta"]'::jsonb, '["stovetop"]'::jsonb, '["italian","comfort","hearty","lentils","tofu","pasta","chopped tomatoes","onion","garlic","olive oil","stovetop","dinner"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 151),
  ('d-chickpea-tofu-spinach-curry', 'Chickpea, Tofu and Spinach Curry', 'Chickpeas and tofu simmered in a tomato and coconut curry with spinach', 'dinner', 'chickpeas', '🍛', 25, 'balanced', 797, 58, 68, 39, 25, 16, 839, '[{"name":"chickpeas","amount":200,"unit":"g"},{"name":"tofu","amount":220,"unit":"g"},{"name":"spinach","amount":100,"unit":"g"},{"name":"chopped tomatoes","amount":200,"unit":"g"},{"name":"onion","amount":60,"unit":"g"},{"name":"coconut milk","amount":40,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 tbsp curry powder","pinch of salt"]'::jsonb, '["Dice the onion and soften it in the oil in a deep pan over medium heat for 4 minutes, then stir in the curry powder","Cut the tofu into cubes and add it with the drained chickpeas, the chopped tomatoes and the coconut milk","Simmer for 12 minutes until the sauce has thickened","Stir in the spinach until wilted, season with salt and serve"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","hearty","chickpeas","tofu","spinach","chopped tomatoes","onion","coconut milk","oil","stovetop","dinner"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 152),
  ('d-bean-tofu-chili', 'Bean and Tofu Chili', 'A thick chili of kidney beans and crumbled tofu with peppers and corn, over a little rice', 'dinner', 'kidney beans', '🌶️', 30, 'balanced', 830, 61, 98, 28, 25, 23, 911, '[{"name":"kidney beans","amount":200,"unit":"g"},{"name":"tofu","amount":220,"unit":"g"},{"name":"chopped tomatoes","amount":250,"unit":"g"},{"name":"peppers","amount":100,"unit":"g"},{"name":"onion","amount":60,"unit":"g"},{"name":"corn","amount":60,"unit":"g"},{"name":"rice","amount":25,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 tsp cumin","1 tsp smoked paprika","pinch of chili flakes","pinch of salt"]'::jsonb, '["Cook the rice in {60} ml of salted water, covered, for 12 minutes","Dice the onion and the peppers and soften them in the oil in a pot over medium heat for 4 minutes","Crumble in the tofu, add the cumin, smoked paprika and chili flakes and fry for 4 minutes","Add the drained beans, the corn and the chopped tomatoes and simmer for 15 minutes until thick","Season with salt and serve over the rice"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","spicy","comfort","hearty","kidney beans","tofu","chopped tomatoes","peppers","onion","corn","rice","oil","stovetop","dinner"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 153),
  ('d-crispy-tofu-quinoa-greens', 'Crispy Tofu with Quinoa and Greens', 'A big bowl of crisp tofu, quinoa, broccoli and peas with soy sauce', 'dinner', 'tofu', '🥦', 25, 'balanced', 811, 67, 67, 37, 19, 9, 1210, '[{"name":"tofu","amount":280,"unit":"g"},{"name":"quinoa","amount":50,"unit":"g"},{"name":"peas","amount":120,"unit":"g"},{"name":"broccoli","amount":150,"unit":"g"},{"name":"soy sauce","amount":15,"unit":"ml"},{"name":"oil","amount":8,"unit":"g"}]'::jsonb, '[]'::jsonb, '["Rinse the quinoa and simmer it in {130} ml of water, covered, for 12 minutes, then fluff it with a fork","Pat the tofu very dry and cut it into cubes; cut the broccoli into small florets","Heat the oil in a wide pan over medium-high heat and fry the tofu for 8 minutes, turning, until crisp on all sides","Add the broccoli, the peas and a splash of water, cover and steam for 4 minutes","Pour over the soy sauce, toss and serve on the quinoa"]'::jsonb, '["stovetop"]'::jsonb, '["asian","hearty","tofu","quinoa","peas","broccoli","soy sauce","oil","stovetop","dinner"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 154),
  ('d-lentil-tofu-dal', 'Lentil and Tofu Dal', 'Lentils cooked soft with tomato, coconut and spices, with tofu and spinach stirred in', 'dinner', 'lentils', '🥣', 30, 'balanced', 764, 60, 72, 33, 19, 8, 292, '[{"name":"lentils","amount":80,"unit":"g"},{"name":"tofu","amount":200,"unit":"g"},{"name":"spinach","amount":100,"unit":"g"},{"name":"chopped tomatoes","amount":150,"unit":"g"},{"name":"onion","amount":60,"unit":"g"},{"name":"coconut milk","amount":40,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 tbsp curry powder","pinch of turmeric","pinch of salt"]'::jsonb, '["Dice the onion and soften it in the oil in a pot over medium heat for 4 minutes, then stir in the curry powder and turmeric","Add the rinsed lentils, the chopped tomatoes, the coconut milk and {400} ml of water and simmer for 20 minutes, stirring now and then, until the lentils fall apart","Cut the tofu into cubes and add it with the spinach; cook for 3 more minutes","Season with salt and serve"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","hearty","lentils","tofu","spinach","chopped tomatoes","onion","coconut milk","oil","stovetop","dinner"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 155),
  ('d-garlic-tofu-steaks-potatoes', 'Garlic Tofu Steaks with Potatoes and Green Beans', 'Thick slices of tofu seared with garlic, with boiled potatoes and green beans', 'dinner', 'tofu', '🥔', 25, 'balanced', 787, 61, 69, 37, 18, 9, 71, '[{"name":"tofu","amount":300,"unit":"g"},{"name":"potatoes","amount":250,"unit":"g"},{"name":"green beans","amount":200,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"},{"name":"olive oil","amount":10,"unit":"g"}]'::jsonb, '["1 tsp smoked paprika","pinch of salt","black pepper"]'::jsonb, '["Cut the potatoes into chunks and boil them in salted water for 15 minutes, adding the trimmed green beans for the last 5 minutes, then drain","Pat the tofu dry and cut it into thick slices; season with salt, black pepper and the smoked paprika","Heat the olive oil in a pan over medium-high heat and sear the tofu for 4 minutes on each side until deep golden","Add the sliced garlic for the last minute, then serve the tofu with the potatoes and the green beans, spooning the garlic oil over"]'::jsonb, '["stovetop"]'::jsonb, '["hearty","tofu","potatoes","green beans","garlic","olive oil","stovetop","dinner"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 156),
  ('l-chicken-fried-rice', 'Chicken Fried Rice', 'Wok-fried rice with chicken, egg, peas and carrots', 'lunch', 'chicken', '🍚', 20, 'quick', 646, 43, 72, 19, 5, 6, 1049, '[{"name":"chicken","amount":120,"unit":"g"},{"name":"rice","amount":70,"unit":"g"},{"name":"eggs","amount":1,"unit":"","label":"1 egg"},{"name":"peas","amount":50,"unit":"g"},{"name":"carrots","amount":50,"unit":"g"},{"name":"onion","amount":30,"unit":"g"},{"name":"soy sauce","amount":15,"unit":"g"},{"name":"oil","amount":10,"unit":"g"}]'::jsonb, '["black pepper","1 tsp grated ginger"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes, drain and spread on a plate to steam dry","Cut the chicken into small pieces, dice the onion and carrots, and fry them in the oil over high heat for 5 minutes until the chicken is cooked through","Add the peas and ginger, then push everything aside, crack in the egg and scramble it in the empty half of the pan","Add the rice and soy sauce and stir-fry for 2 minutes until everything is hot and coated"]'::jsonb, '["stovetop"]'::jsonb, '["asian","quick","chicken","rice","eggs","peas","carrots","onion","soy sauce","oil","stovetop","lunch"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, 157),
  ('l-teriyaki-salmon-rice-bowl', 'Teriyaki Salmon Rice Bowl', 'Glazed salmon over rice with broccoli and carrot', 'lunch', 'salmon', '🍣', 25, 'balanced', 651, 37, 72, 23, 5, 8, 1298, '[{"name":"salmon","amount":130,"unit":"g"},{"name":"rice","amount":70,"unit":"g"},{"name":"broccoli","amount":100,"unit":"g"},{"name":"carrots","amount":50,"unit":"g"},{"name":"teriyaki","amount":30,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["salt","sesame seeds if you have them"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes; add the broccoli florets to the pot for the last 3 minutes, then drain","Heat the oil in a pan over medium-high heat and cook the salmon for 3 minutes per side","Pour the teriyaki over the salmon and let it bubble for 1 minute, spooning the glaze over the fish","Serve the salmon on the rice with the broccoli and the carrots, coarsely grated, and pour over any glaze left in the pan"]'::jsonb, '["stovetop"]'::jsonb, '["asian","hearty","salmon","rice","broccoli","carrots","teriyaki","oil","stovetop","lunch"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, 158),
  ('l-tofu-broccoli-stir-fry', 'Tofu and Broccoli Stir-Fry', 'Crispy tofu with broccoli and peppers in a garlic soy sauce, on rice', 'lunch', 'tofu', '🥦', 20, 'quick', 587, 36, 68, 22, 9, 6, 892, '[{"name":"tofu","amount":150,"unit":"g"},{"name":"rice","amount":60,"unit":"g"},{"name":"broccoli","amount":120,"unit":"g"},{"name":"peppers","amount":80,"unit":"g"},{"name":"soy sauce","amount":15,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"},{"name":"oil","amount":8,"unit":"g"}]'::jsonb, '["1 tsp grated ginger","black pepper"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes and drain","Pat the tofu dry, cut it into cubes and fry it in the oil over medium-high heat for 6 minutes, turning, until golden on all sides","Add the broccoli in small florets, the sliced peppers and a splash of water and stir-fry for 4 minutes","Stir in the chopped garlic, ginger, pepper and soy sauce, cook 1 more minute and serve over the rice"]'::jsonb, '["stovetop"]'::jsonb, '["asian","quick","tofu","rice","broccoli","peppers","soy sauce","garlic","oil","stovetop","lunch"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 159),
  ('l-shrimp-noodle-stir-fry', 'Shrimp Noodle Stir-Fry', 'Quick stir-fried noodles with shrimp, peppers and carrot', 'lunch', 'shrimp', '🍜', 15, 'quick', 511, 39, 63, 12, 6, 8, 1032, '[{"name":"shrimp","amount":130,"unit":"g"},{"name":"noodles","amount":70,"unit":"g"},{"name":"peppers","amount":80,"unit":"g"},{"name":"carrots","amount":50,"unit":"g"},{"name":"onion","amount":30,"unit":"g"},{"name":"soy sauce","amount":15,"unit":"g"},{"name":"oil","amount":8,"unit":"g"}]'::jsonb, '["1 tsp grated ginger","squeeze of lime juice"]'::jsonb, '["Cook the noodles in boiling water according to the packet, usually 4 minutes, then drain and rinse briefly","Slice the peppers and onion and cut the carrots into thin strips, then stir-fry them in the oil over high heat for 3 minutes","Add the shrimp and ginger and cook for 2 to 3 minutes until the shrimp are pink","Toss in the noodles and soy sauce, heat through for 1 minute and finish with lime juice"]'::jsonb, '["stovetop"]'::jsonb, '["asian","quick","light","shrimp","noodles","peppers","carrots","onion","soy sauce","oil","stovetop","lunch"]'::jsonb, '["dairy-free","nut-allergy","halal"]'::jsonb, 160),
  ('l-peanut-chicken-noodle-salad', 'Peanut Chicken Noodle Salad', 'Cold noodles with chicken, cucumber and a peanut dressing', 'lunch', 'chicken', '🥜', 20, 'quick', 532, 42, 55, 16, 5, 7, 737, '[{"name":"chicken","amount":120,"unit":"g"},{"name":"noodles","amount":60,"unit":"g"},{"name":"cucumber","amount":80,"unit":"g"},{"name":"carrots","amount":50,"unit":"g"},{"name":"peanut butter","amount":20,"unit":"g"},{"name":"soy sauce","amount":10,"unit":"g"}]'::jsonb, '["squeeze of lime juice","2 tbsp warm water"]'::jsonb, '["Simmer the chicken in lightly salted water for 12 minutes until cooked through, then shred it with two forks","Cook the noodles according to the packet, drain and rinse under cold water until cool","Whisk the peanut butter with the soy sauce, lime juice and warm water into a pourable dressing","Cut the cucumber and carrots into thin strips and toss everything together with the dressing"]'::jsonb, '["stovetop"]'::jsonb, '["asian","fresh","quick","light","chicken","noodles","cucumber","carrots","peanut butter","soy sauce","stovetop","lunch"]'::jsonb, '["dairy-free","halal","kosher"]'::jsonb, 161),
  ('l-egg-fried-rice', 'Egg Fried Rice with Peas', 'Simple fried rice with scrambled egg, peas and carrot', 'lunch', 'eggs', '🍳', 18, 'quick', 605, 24, 77, 21, 6, 7, 920, '[{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"rice","amount":75,"unit":"g"},{"name":"peas","amount":60,"unit":"g"},{"name":"carrots","amount":50,"unit":"g"},{"name":"onion","amount":30,"unit":"g"},{"name":"soy sauce","amount":12,"unit":"g"},{"name":"oil","amount":10,"unit":"g"}]'::jsonb, '["black pepper"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes, drain and let it steam dry for a few minutes","Finely dice the onion and carrots and fry them in the oil over high heat for 3 minutes, then add the peas","Push the vegetables aside, crack in the eggs and scramble them until just set","Add the rice and soy sauce, stir-fry for 2 minutes and season with pepper"]'::jsonb, '["stovetop"]'::jsonb, '["asian","quick","eggs","rice","peas","carrots","onion","soy sauce","oil","stovetop","lunch"]'::jsonb, '["vegetarian","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 162),
  ('l-spicy-beef-lettuce-cups', 'Spicy Beef Lettuce Cups', 'Chili-garlic beef mince with rice, served in crisp lettuce leaves', 'lunch', 'beef mince', '🥬', 20, 'quick', 559, 31, 51, 25, 4, 3, 790, '[{"name":"beef mince","amount":130,"unit":"g"},{"name":"rice","amount":50,"unit":"g"},{"name":"lettuce","amount":80,"unit":"g"},{"name":"carrots","amount":50,"unit":"g"},{"name":"soy sauce","amount":12,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1/2 tsp chili flakes","1 tsp grated ginger","squeeze of lime juice"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes and drain","Brown the beef mince in the oil over high heat for 5 minutes, breaking it up","Add the chopped garlic, ginger, chili flakes and soy sauce and cook for 2 minutes","Separate the lettuce into cups, fill them with rice, beef and the grated carrots and finish with lime juice"]'::jsonb, '["stovetop"]'::jsonb, '["asian","spicy","fresh","quick","beef mince","rice","lettuce","carrots","soy sauce","garlic","oil","stovetop","lunch"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, 163),
  ('l-coconut-chickpea-curry', 'Spicy Coconut Chickpea Curry', 'Chickpeas and spinach simmered in a spiced coconut tomato sauce', 'lunch', 'chickpeas', '🍛', 20, 'quick', 524, 17, 52, 31, 15, 12, 621, '[{"name":"chickpeas","amount":150,"unit":"g"},{"name":"coconut milk","amount":100,"unit":"g"},{"name":"chopped tomatoes","amount":150,"unit":"g"},{"name":"spinach","amount":80,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 tbsp curry powder","1/2 tsp chili flakes","salt"]'::jsonb, '["Dice the onion and soften it in the oil over medium heat for 4 minutes, then add the chopped garlic, curry powder and chili flakes for 1 minute","Add the chopped tomatoes, coconut milk and drained chickpeas and simmer for 10 minutes","Stir in the spinach until it wilts and season with salt"]'::jsonb, '["stovetop"]'::jsonb, '["asian","spicy","comfort","quick","light","chickpeas","coconut milk","chopped tomatoes","spinach","onion","garlic","oil","stovetop","lunch"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 164),
  ('l-teriyaki-chicken-rice-bowl', 'Teriyaki Chicken Rice Bowl', 'Sticky teriyaki chicken with rice, broccoli and carrot', 'lunch', 'chicken', '🍗', 20, 'quick', 541, 40, 73, 9, 5, 9, 1471, '[{"name":"chicken","amount":130,"unit":"g"},{"name":"rice","amount":70,"unit":"g"},{"name":"broccoli","amount":100,"unit":"g"},{"name":"carrots","amount":50,"unit":"g"},{"name":"teriyaki","amount":35,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["sesame seeds if you have them"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes, adding the broccoli florets and sliced carrots for the last 3 minutes, then drain","Cut the chicken into bite-sized pieces and fry in the oil over medium-high heat for 6 minutes until golden and cooked through","Add the teriyaki and let it bubble for 1 minute until sticky","Serve the chicken and its sauce over the rice and vegetables"]'::jsonb, '["stovetop"]'::jsonb, '["asian","quick","light","chicken","rice","broccoli","carrots","teriyaki","oil","stovetop","lunch"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, 165),
  ('l-ginger-turkey-noodle-soup', 'Ginger Turkey Noodle Soup', 'Light broth with turkey, noodles, mushrooms and spinach', 'lunch', 'turkey', '🍲', 20, 'quick', 423, 38, 47, 10, 5, 5, 836, '[{"name":"turkey","amount":110,"unit":"g"},{"name":"noodles","amount":50,"unit":"g"},{"name":"mushrooms","amount":60,"unit":"g"},{"name":"carrots","amount":60,"unit":"g"},{"name":"spinach","amount":50,"unit":"g"},{"name":"soy sauce","amount":12,"unit":"g"},{"name":"garlic","amount":4,"unit":"g","label":"1 clove"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 stock cube","{500} ml water","1 tbsp grated ginger"]'::jsonb, '["Slice the turkey thinly and brown it in the oil in a pot for 3 minutes with the chopped garlic and ginger","Add the water, stock cube, sliced carrots and mushrooms and simmer for 6 minutes","Add the noodles and cook for 4 minutes until soft","Stir in the spinach and soy sauce and serve as soon as the spinach wilts"]'::jsonb, '["stovetop"]'::jsonb, '["asian","quick","light","turkey","noodles","mushrooms","carrots","spinach","soy sauce","garlic","oil","stovetop","lunch"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, 166),
  ('l-spicy-tofu-fried-rice', 'Spicy Tofu Fried Rice', 'Fried rice with golden tofu, peas, peppers and chili', 'lunch', 'tofu', '🌶️', 20, 'quick', 611, 32, 75, 22, 9, 7, 936, '[{"name":"tofu","amount":130,"unit":"g"},{"name":"rice","amount":70,"unit":"g"},{"name":"peas","amount":50,"unit":"g"},{"name":"carrots","amount":50,"unit":"g"},{"name":"peppers","amount":50,"unit":"g"},{"name":"soy sauce","amount":15,"unit":"g"},{"name":"oil","amount":10,"unit":"g"}]'::jsonb, '["1/2 tsp chili flakes","1 tsp grated ginger"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes, drain and let it steam dry","Cut the tofu into small cubes and fry in the oil over high heat for 5 minutes until golden","Add the diced carrots and peppers, the peas, ginger and chili flakes and stir-fry for 3 minutes","Add the rice and soy sauce and fry for 2 more minutes"]'::jsonb, '["stovetop"]'::jsonb, '["asian","spicy","quick","tofu","rice","peas","carrots","peppers","soy sauce","oil","stovetop","lunch"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 167),
  ('l-spicy-tuna-rice-bowl', 'Spicy Tuna Rice Bowl', 'Rice bowl with tuna, avocado, cucumber and a spicy soy dressing', 'lunch', 'tuna', '🐟', 15, 'quick', 599, 29, 75, 22, 12, 4, 839, '[{"name":"tuna","amount":100,"unit":"g"},{"name":"rice","amount":70,"unit":"g"},{"name":"avocado","amount":1,"unit":"","label":"1 avocado"},{"name":"cucumber","amount":80,"unit":"g"},{"name":"carrots","amount":40,"unit":"g"},{"name":"soy sauce","amount":10,"unit":"g"}]'::jsonb, '["1 tsp sriracha or other chili sauce","squeeze of lime juice"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes, drain and let it cool slightly","Mix the drained tuna with the soy sauce, chili sauce and lime juice","Dice the avocado and cucumber and grate the carrots","Fill a bowl with the rice and arrange the tuna, avocado, cucumber and carrots on top"]'::jsonb, '["stovetop"]'::jsonb, '["asian","spicy","fresh","quick","tuna","rice","avocado","cucumber","carrots","soy sauce","stovetop","lunch"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, 168),
  ('l-chicken-fajita-wraps', 'Chicken Fajita Wraps', 'Spiced chicken, peppers and onion in warm tortillas', 'lunch', 'chicken', '🌯', 20, 'quick', 640, 41, 70, 21, 7, 11, 948, '[{"name":"chicken","amount":130,"unit":"g"},{"name":"tortilla","amount":2,"unit":"","label":"2 tortillas"},{"name":"peppers","amount":100,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"oil","amount":8,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1 tsp paprika","salt","squeeze of lime juice"]'::jsonb, '["Slice the chicken, peppers and onion into strips and toss the chicken with the cumin, paprika and salt","Fry the chicken in the oil over high heat for 5 minutes until browned and cooked through","Add the peppers and onion and cook for 4 minutes until soft with charred edges","Warm the tortillas in a dry pan, fill them and finish with lime juice"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","quick","chicken","tortilla","peppers","onion","oil","stovetop","lunch"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, 169),
  ('l-bean-cheese-quesadilla', 'Bean and Cheese Quesadilla', 'Crisp tortilla filled with kidney beans, corn and melted cheese', 'lunch', 'kidney beans', '🧀', 12, 'quick', 675, 29, 91, 22, 11, 13, 1528, '[{"name":"tortilla","amount":2,"unit":"","label":"2 tortillas"},{"name":"kidney beans","amount":100,"unit":"g"},{"name":"cheese","amount":40,"unit":"g"},{"name":"corn","amount":40,"unit":"g"},{"name":"tomato","amount":80,"unit":"g"}]'::jsonb, '["1/2 tsp ground cumin","pinch of salt"]'::jsonb, '["Roughly mash the drained kidney beans with the cumin and salt, then stir in the corn","Spread the beans over one tortilla, scatter over the grated cheese and top with the second tortilla","Cook in a dry pan over medium heat for 2 to 3 minutes per side until crisp and the cheese has melted","Cut into wedges and serve with the diced tomato"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","quick","tortilla","kidney beans","cheese","corn","tomato","stovetop","lunch"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, 170),
  ('l-chicken-burrito-bowl', 'Chicken Burrito Bowl', 'Rice bowl with spiced chicken, beans, corn, tomato and lettuce', 'lunch', 'chicken', '🥗', 20, 'quick', 573, 42, 77, 11, 8, 8, 356, '[{"name":"chicken","amount":130,"unit":"g"},{"name":"rice","amount":60,"unit":"g"},{"name":"kidney beans","amount":80,"unit":"g"},{"name":"corn","amount":50,"unit":"g"},{"name":"tomato","amount":80,"unit":"g"},{"name":"lettuce","amount":40,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1 tsp paprika","salt","squeeze of lime juice"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes and drain","Cut the chicken into small pieces, coat with the cumin, paprika and salt and fry in the oil for 6 minutes until cooked through","Warm the drained kidney beans and corn in the same pan for 1 minute","Fill a bowl with the rice, chicken, beans and corn, top with diced tomato and shredded lettuce and squeeze over lime juice"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","fresh","quick","chicken","rice","kidney beans","corn","tomato","lettuce","oil","stovetop","lunch"]'::jsonb, '["gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 171),
  ('l-beef-tacos', 'Beef Tacos', 'Spiced beef mince in soft tortillas with lettuce, tomato and cheese', 'lunch', 'beef mince', '🌮', 20, 'quick', 730, 39, 67, 33, 7, 9, 1135, '[{"name":"beef mince","amount":120,"unit":"g"},{"name":"tortilla","amount":2,"unit":"","label":"2 tortillas"},{"name":"lettuce","amount":40,"unit":"g"},{"name":"tomato","amount":80,"unit":"g"},{"name":"cheese","amount":20,"unit":"g"},{"name":"onion","amount":30,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1 tsp paprika","1/2 tsp chili flakes","salt"]'::jsonb, '["Brown the beef mince with the diced onion in a dry pan over high heat for 6 minutes","Stir in the cumin, paprika, chili flakes, salt and a splash of water and cook for 2 more minutes","Warm the tortillas in a dry pan","Fill them with the beef, shredded lettuce, diced tomato and grated cheese"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","spicy","quick","hearty","beef mince","tortilla","lettuce","tomato","cheese","onion","stovetop","lunch"]'::jsonb, '["nut-allergy","halal"]'::jsonb, 172),
  ('l-sweet-potato-bean-burrito', 'Sweet Potato and Bean Burrito', 'Burrito filled with spiced sweet potato, kidney beans and corn', 'lunch', 'kidney beans', '🍠', 25, 'balanced', 534, 16, 87, 15, 13, 14, 837, '[{"name":"tortilla","amount":1,"unit":"","label":"1 tortilla"},{"name":"sweet potato","amount":150,"unit":"g"},{"name":"kidney beans","amount":100,"unit":"g"},{"name":"corn","amount":40,"unit":"g"},{"name":"oil","amount":8,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1/2 tsp smoked paprika","salt","squeeze of lime juice"]'::jsonb, '["Peel the sweet potato and cut it into 1 cm cubes","Fry it in the oil over medium heat for 12 minutes, turning now and then, until tender and browned","Add the drained kidney beans, corn, cumin, paprika and salt and cook for 2 minutes, lightly crushing some of the beans","Warm the tortilla, pile the filling down the middle, add lime juice, fold in the sides and roll up"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","light","tortilla","sweet potato","kidney beans","corn","oil","stovetop","lunch"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 173),
  ('l-shrimp-avocado-tacos', 'Shrimp and Avocado Tacos', 'Chili-lime shrimp in tortillas with avocado, tomato and lettuce', 'lunch', 'shrimp', '🍤', 15, 'quick', 767, 40, 76, 36, 15, 8, 1055, '[{"name":"shrimp","amount":130,"unit":"g"},{"name":"tortilla","amount":2,"unit":"","label":"2 tortillas"},{"name":"avocado","amount":1,"unit":"","label":"1 avocado"},{"name":"tomato","amount":80,"unit":"g"},{"name":"lettuce","amount":40,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1/2 tsp chili flakes","1/2 tsp ground cumin","squeeze of lime juice","salt"]'::jsonb, '["Toss the shrimp with the chili flakes, cumin and salt and fry in the oil over high heat for 2 to 3 minutes until pink","Mash the avocado with lime juice and a pinch of salt","Warm the tortillas in a dry pan and spread them with the avocado","Top with the shrimp, diced tomato and shredded lettuce"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","spicy","fresh","quick","hearty","shrimp","tortilla","avocado","tomato","lettuce","oil","stovetop","lunch"]'::jsonb, '["dairy-free","nut-allergy","halal"]'::jsonb, 174),
  ('l-chicken-tortilla-soup', 'Chicken Tortilla Soup', 'Tomato broth with chicken, beans and corn, topped with crisp tortilla strips', 'lunch', 'chicken', '🍲', 25, 'balanced', 534, 40, 62, 15, 11, 14, 989, '[{"name":"chicken","amount":120,"unit":"g"},{"name":"chopped tomatoes","amount":200,"unit":"g"},{"name":"corn","amount":60,"unit":"g"},{"name":"kidney beans","amount":60,"unit":"g"},{"name":"onion","amount":40,"unit":"g"},{"name":"tortilla","amount":1,"unit":"","label":"1 tortilla"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1/2 tsp chili flakes","1 stock cube","{300} ml water","squeeze of lime juice"]'::jsonb, '["Cut the tortilla into thin strips and toast them in a dry pot over medium heat for 3 minutes until crisp, then set aside","Soften the diced onion in the oil for 3 minutes, then add the cumin and chili flakes","Add the chopped tomatoes, water, stock cube and the chicken in small pieces and simmer for 12 minutes","Stir in the drained kidney beans and corn, heat for 2 minutes, add lime juice and serve topped with the tortilla strips"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","spicy","comfort","light","chicken","chopped tomatoes","corn","kidney beans","onion","tortilla","oil","stovetop","lunch"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, 175),
  ('l-smoky-bean-chili', 'Smoky Bean Chili', 'Kidney bean and vegetable chili with rice', 'lunch', 'kidney beans', '🌶️', 25, 'balanced', 546, 20, 96, 11, 16, 18, 687, '[{"name":"kidney beans","amount":150,"unit":"g"},{"name":"chopped tomatoes","amount":200,"unit":"g"},{"name":"peppers","amount":80,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"corn","amount":50,"unit":"g"},{"name":"rice","amount":50,"unit":"g"},{"name":"oil","amount":8,"unit":"g"}]'::jsonb, '["1 tsp smoked paprika","1 tsp ground cumin","1/2 tsp chili flakes","salt"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes and drain","Dice the onion and peppers and soften them in the oil for 5 minutes, then stir in the paprika, cumin and chili flakes","Add the chopped tomatoes and drained kidney beans and simmer for 12 minutes until thick","Stir in the corn, season with salt and serve over the rice"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","spicy","comfort","light","kidney beans","chopped tomatoes","peppers","onion","corn","rice","oil","stovetop","lunch"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 176),
  ('l-huevos-rancheros', 'Huevos Rancheros', 'Fried eggs on tortillas with beans and a spicy tomato sauce', 'lunch', 'eggs', '🍳', 20, 'quick', 726, 31, 84, 29, 11, 12, 1363, '[{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"tortilla","amount":2,"unit":"","label":"2 tortillas"},{"name":"kidney beans","amount":80,"unit":"g"},{"name":"chopped tomatoes","amount":120,"unit":"g"},{"name":"onion","amount":30,"unit":"g"},{"name":"oil","amount":8,"unit":"g"}]'::jsonb, '["1/2 tsp chili flakes","1/2 tsp ground cumin","salt"]'::jsonb, '["Soften the diced onion in half the oil for 3 minutes, add the chili flakes and cumin, then the chopped tomatoes, and simmer for 6 minutes","Stir in the drained kidney beans and warm through","Fry the eggs in the remaining oil for 2 to 3 minutes until the whites are set","Warm the tortillas in a dry pan, spoon over the beans and sauce and top each with an egg"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","spicy","quick","hearty","eggs","tortilla","kidney beans","chopped tomatoes","onion","oil","stovetop","lunch"]'::jsonb, '["vegetarian","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 177),
