  ('l-minestrone', 'Minestrone', 'Chunky vegetable and bean soup with pasta and parmesan', 'lunch', 'kidney beans', '🥣', 30, 'balanced', 444, 19, 66, 13, 13, 16, 584, '[{"name":"kidney beans","amount":80,"unit":"g"},{"name":"pasta","amount":40,"unit":"g"},{"name":"carrots","amount":60,"unit":"g"},{"name":"zucchini","amount":80,"unit":"g"},{"name":"chopped tomatoes","amount":200,"unit":"g"},{"name":"onion","amount":40,"unit":"g"},{"name":"olive oil","amount":8,"unit":"g"},{"name":"parmesan","amount":10,"unit":"g"}]'::jsonb, '["1 stock cube","{400} ml water","1 tsp dried oregano","black pepper"]'::jsonb, '["Dice the onion, carrots and zucchini and soften them in the olive oil in a pot for 5 minutes","Add the chopped tomatoes, water, stock cube and oregano and simmer for 10 minutes","Add the pasta and drained kidney beans and cook for 8 to 10 minutes until the pasta is tender","Serve topped with the grated parmesan and black pepper"]'::jsonb, '["stovetop"]'::jsonb, '["italian","comfort","light","kidney beans","pasta","carrots","zucchini","chopped tomatoes","onion","olive oil","parmesan","stovetop","lunch"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, 183),
  ('l-chicken-pesto-pasta', 'Chicken Pesto Pasta', 'Pasta with pan-fried chicken, pesto, spinach and tomato', 'lunch', 'chicken', '🍝', 20, 'quick', 536, 40, 59, 15, 5, 5, 351, '[{"name":"chicken","amount":120,"unit":"g"},{"name":"pasta","amount":70,"unit":"g"},{"name":"pesto","amount":25,"unit":"g"},{"name":"spinach","amount":50,"unit":"g"},{"name":"tomato","amount":80,"unit":"g"}]'::jsonb, '["salt","black pepper"]'::jsonb, '["Cook the pasta in salted boiling water according to the packet and drain, keeping a little of the water","Cut the chicken into strips, season and fry in a non-stick pan over medium-high heat for 6 minutes until golden","Add the diced tomato and spinach and cook for 1 minute until the spinach wilts","Toss in the pasta, pesto and a splash of the pasta water"]'::jsonb, '["stovetop"]'::jsonb, '["italian","quick","light","chicken","pasta","pesto","spinach","tomato","stovetop","lunch"]'::jsonb, '["halal"]'::jsonb, 184),
  ('l-spinach-mushroom-frittata', 'Spinach and Mushroom Frittata', 'Thick Italian omelette with mushrooms, spinach and parmesan, with bread', 'lunch', 'eggs', '🍳', 20, 'quick', 497, 35, 24, 29, 5, 5, 623, '[{"name":"eggs","amount":3,"unit":"","label":"3 eggs"},{"name":"spinach","amount":60,"unit":"g"},{"name":"mushrooms","amount":80,"unit":"g"},{"name":"parmesan","amount":15,"unit":"g"},{"name":"onion","amount":30,"unit":"g"},{"name":"olive oil","amount":8,"unit":"g"},{"name":"bread","amount":35,"unit":"g","label":"1 slice"}]'::jsonb, '["salt","black pepper"]'::jsonb, '["Slice the mushrooms and onion and fry them in the olive oil in a small non-stick pan for 5 minutes","Add the spinach and let it wilt","Beat the eggs with the grated parmesan, salt and pepper, pour over the vegetables and cook over low heat, covered, for 6 to 8 minutes until set","Slide onto a plate and serve with the bread"]'::jsonb, '["stovetop"]'::jsonb, '["italian","quick","light","eggs","spinach","mushrooms","parmesan","onion","olive oil","bread","stovetop","lunch"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, 185),
  ('l-pasta-e-ceci', 'Pasta e Ceci', 'Thick Italian chickpea and pasta soup with tomato and garlic', 'lunch', 'chickpeas', '🥣', 25, 'balanced', 509, 17, 80, 15, 14, 14, 501, '[{"name":"chickpeas","amount":120,"unit":"g"},{"name":"pasta","amount":50,"unit":"g"},{"name":"chopped tomatoes","amount":150,"unit":"g"},{"name":"onion","amount":40,"unit":"g"},{"name":"carrots","amount":40,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"},{"name":"olive oil","amount":10,"unit":"g"}]'::jsonb, '["1 stock cube","{350} ml water","1 tsp dried rosemary","black pepper"]'::jsonb, '["Finely dice the onion and carrots and soften them in the olive oil for 5 minutes, then add the chopped garlic and rosemary","Add the chopped tomatoes, water, stock cube and drained chickpeas and simmer for 8 minutes","Crush some of the chickpeas against the side of the pot to thicken the soup","Add the pasta and cook for 8 to 10 minutes, stirring, until tender, then season with pepper"]'::jsonb, '["stovetop"]'::jsonb, '["italian","comfort","light","chickpeas","pasta","chopped tomatoes","onion","carrots","garlic","olive oil","stovetop","lunch"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 186),
  ('l-turkey-bolognese', 'Quick Turkey Bolognese', 'Lean turkey mince in a tomato sauce with pasta', 'lunch', 'turkey mince', '🍝', 25, 'balanced', 544, 35, 66, 16, 7, 9, 276, '[{"name":"turkey mince","amount":120,"unit":"g"},{"name":"pasta","amount":70,"unit":"g"},{"name":"chopped tomatoes","amount":150,"unit":"g"},{"name":"onion","amount":40,"unit":"g"},{"name":"carrots","amount":40,"unit":"g"},{"name":"garlic","amount":4,"unit":"g","label":"1 clove"},{"name":"olive oil","amount":5,"unit":"g"}]'::jsonb, '["1 tsp dried oregano","salt","black pepper"]'::jsonb, '["Finely dice the onion and carrots and soften them in the olive oil for 4 minutes","Add the turkey mince and brown it for 5 minutes, then stir in the chopped garlic and oregano","Add the chopped tomatoes and simmer for 10 minutes","Meanwhile cook the pasta in salted boiling water, drain and toss with the sauce"]'::jsonb, '["stovetop"]'::jsonb, '["italian","comfort","light","turkey mince","pasta","chopped tomatoes","onion","carrots","garlic","olive oil","stovetop","lunch"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, 187),
  ('l-garlic-shrimp-spaghetti', 'Garlic Chili Shrimp Spaghetti', 'Spaghetti with shrimp, garlic, chili, tomato and spinach', 'lunch', 'shrimp', '🍤', 15, 'quick', 540, 39, 65, 14, 5, 5, 198, '[{"name":"shrimp","amount":130,"unit":"g"},{"name":"pasta","amount":75,"unit":"g"},{"name":"garlic","amount":12,"unit":"g","label":"3 cloves"},{"name":"tomato","amount":100,"unit":"g"},{"name":"spinach","amount":40,"unit":"g"},{"name":"olive oil","amount":12,"unit":"g"}]'::jsonb, '["1/2 tsp chili flakes","salt","squeeze of lemon juice"]'::jsonb, '["Cook the pasta in salted boiling water according to the packet and drain, keeping a little of the water","Warm the olive oil in a pan and gently fry the sliced garlic and chili flakes for 1 minute","Add the shrimp and diced tomato and cook for 3 minutes until the shrimp are pink","Toss in the pasta, spinach and a splash of pasta water and finish with lemon juice"]'::jsonb, '["stovetop"]'::jsonb, '["italian","spicy","quick","light","shrimp","pasta","garlic","tomato","spinach","olive oil","stovetop","lunch"]'::jsonb, '["dairy-free","nut-allergy","halal"]'::jsonb, 188),
  ('l-salmon-pesto-pasta', 'Salmon and Pea Pesto Pasta', 'Pasta with flaked salmon, peas and pesto', 'lunch', 'salmon', '🐟', 20, 'quick', 594, 34, 57, 24, 5, 5, 322, '[{"name":"salmon","amount":110,"unit":"g"},{"name":"pasta","amount":65,"unit":"g"},{"name":"pesto","amount":20,"unit":"g"},{"name":"peas","amount":50,"unit":"g"}]'::jsonb, '["salt","black pepper","squeeze of lemon juice"]'::jsonb, '["Cook the pasta in salted boiling water according to the packet, adding the peas for the last 2 minutes, then drain","Fry the salmon in a non-stick pan over medium heat for 3 to 4 minutes per side, then break it into flakes","Toss the pasta and peas with the pesto and fold in the salmon","Season with pepper and lemon juice"]'::jsonb, '["stovetop"]'::jsonb, '["italian","quick","salmon","pasta","pesto","peas","stovetop","lunch"]'::jsonb, '["halal","kosher"]'::jsonb, 189),
  ('l-roasted-vegetable-chickpea-pasta', 'Vegetable and Chickpea Pasta', 'Pasta with zucchini, peppers and chickpeas in tomato sauce', 'lunch', 'chickpeas', '🍝', 25, 'balanced', 534, 19, 90, 13, 13, 17, 295, '[{"name":"chickpeas","amount":100,"unit":"g"},{"name":"pasta","amount":65,"unit":"g"},{"name":"zucchini","amount":100,"unit":"g"},{"name":"peppers","amount":80,"unit":"g"},{"name":"tomato sauce","amount":120,"unit":"g"},{"name":"olive oil","amount":8,"unit":"g"}]'::jsonb, '["1 tsp dried oregano","salt","black pepper"]'::jsonb, '["Cook the pasta in salted boiling water according to the packet and drain","Dice the zucchini and peppers and fry them in the olive oil over medium-high heat for 7 minutes until soft and browned","Add the drained chickpeas, tomato sauce and oregano and simmer for 5 minutes","Toss with the pasta and season"]'::jsonb, '["stovetop"]'::jsonb, '["italian","light","chickpeas","pasta","zucchini","peppers","tomato sauce","olive oil","stovetop","lunch"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 190),
  ('l-chicken-caprese-salad', 'Chicken Caprese Salad', 'Sliced chicken with mozzarella, tomato, lettuce and pesto', 'lunch', 'chicken', '🥗', 15, 'quick', 479, 45, 10, 28, 3, 5, 511, '[{"name":"chicken","amount":130,"unit":"g"},{"name":"mozzarella","amount":60,"unit":"g"},{"name":"tomato","amount":150,"unit":"g"},{"name":"lettuce","amount":50,"unit":"g"},{"name":"pesto","amount":15,"unit":"g"},{"name":"olive oil","amount":5,"unit":"g"}]'::jsonb, '["salt","black pepper"]'::jsonb, '["Season the chicken and fry it in the olive oil over medium heat for 5 to 6 minutes per side until cooked through, then slice","Slice the tomato and mozzarella and arrange them over the lettuce","Top with the chicken and spoon over the pesto"]'::jsonb, '["stovetop"]'::jsonb, '["italian","fresh","quick","light","chicken","mozzarella","tomato","lettuce","pesto","olive oil","stovetop","lunch"]'::jsonb, '["gluten-free","halal"]'::jsonb, 191),
  ('l-greek-chicken-salad', 'Greek Chicken Salad', 'Grilled chicken over cucumber, tomato and lettuce with feta', 'lunch', 'chicken', '🥗', 15, 'quick', 396, 37, 11, 22, 3, 5, 526, '[{"name":"chicken","amount":130,"unit":"g"},{"name":"feta","amount":40,"unit":"g"},{"name":"cucumber","amount":100,"unit":"g"},{"name":"tomato","amount":120,"unit":"g"},{"name":"lettuce","amount":50,"unit":"g"},{"name":"olive oil","amount":10,"unit":"g"}]'::jsonb, '["1 tsp dried oregano","squeeze of lemon juice","salt","black pepper"]'::jsonb, '["Season the chicken with the oregano, salt and pepper and fry in half the olive oil over medium heat for 5 to 6 minutes per side, then slice","Chop the cucumber, tomato and lettuce and put them in a bowl","Top with the chicken and crumbled feta and dress with the remaining olive oil and lemon juice"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","fresh","quick","light","chicken","feta","cucumber","tomato","lettuce","olive oil","stovetop","lunch"]'::jsonb, '["gluten-free","nut-allergy","halal"]'::jsonb, 192),
  ('l-chickpea-couscous-salad', 'Chickpea Couscous Salad', 'Lemony couscous with chickpeas, cucumber, tomato and peppers', 'lunch', 'chickpeas', '🍋', 10, 'quick', 544, 19, 89, 14, 15, 13, 312, '[{"name":"chickpeas","amount":120,"unit":"g"},{"name":"couscous","amount":60,"unit":"g"},{"name":"cucumber","amount":80,"unit":"g"},{"name":"tomato","amount":100,"unit":"g"},{"name":"peppers","amount":60,"unit":"g"},{"name":"olive oil","amount":10,"unit":"g"},{"name":"lemon","amount":1,"unit":"","label":"1 lemon"}]'::jsonb, '["{80} ml boiling water","salt","handful of fresh parsley","1/2 tsp ground cumin"]'::jsonb, '["Put the couscous in a bowl with a pinch of salt, pour over the boiling water, cover and leave for 5 minutes, then fluff with a fork","Dice the cucumber, tomato and peppers","Mix everything with the drained chickpeas, olive oil, the juice of the lemon, cumin and chopped parsley"]'::jsonb, '[]'::jsonb, '["mediterranean","fresh","quick","light","chickpeas","couscous","cucumber","tomato","peppers","olive oil","lemon","lunch"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 193),
  ('l-chickpea-feta-wrap', 'Chickpea and Feta Wrap', 'Tortilla with crushed chickpeas, feta, cucumber, tomato and yogurt', 'lunch', 'chickpeas', '🌯', 10, 'quick', 446, 19, 60, 16, 10, 11, 1052, '[{"name":"tortilla","amount":1,"unit":"","label":"1 tortilla"},{"name":"chickpeas","amount":100,"unit":"g"},{"name":"feta","amount":30,"unit":"g"},{"name":"cucumber","amount":60,"unit":"g"},{"name":"tomato","amount":60,"unit":"g"},{"name":"yogurt","amount":40,"unit":"g"}]'::jsonb, '["1/2 tsp ground cumin","squeeze of lemon juice","black pepper"]'::jsonb, '["Roughly crush the drained chickpeas with a fork and mix them with the yogurt, cumin, lemon juice and pepper","Dice the cucumber and tomato and crumble the feta","Spread the chickpeas over the tortilla, top with the vegetables and feta and roll up tightly"]'::jsonb, '[]'::jsonb, '["mediterranean","fresh","quick","light","tortilla","chickpeas","feta","cucumber","tomato","yogurt","lunch"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, 194),
  ('l-turkish-eggs', 'Turkish Eggs with Garlic Yogurt', 'Poached eggs on garlic yogurt with chili butter and bread', 'lunch', 'eggs', '🍳', 15, 'quick', 557, 36, 38, 29, 4, 9, 592, '[{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"greek yogurt","amount":150,"unit":"g"},{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"butter","amount":10,"unit":"g"},{"name":"garlic","amount":4,"unit":"g","label":"1 clove"}]'::jsonb, '["1/2 tsp chili flakes","1/2 tsp paprika","salt","splash of vinegar"]'::jsonb, '["Stir the finely grated garlic and a pinch of salt into the yogurt and spread it in a shallow bowl","Poach the eggs in barely simmering water with a splash of vinegar for 3 minutes and lift them onto the yogurt","Melt the butter with the chili flakes and paprika until it foams and pour it over the eggs","Serve with the toasted bread"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","spicy","quick","eggs","greek yogurt","bread","butter","garlic","stovetop","lunch"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, 195),
  ('l-tuna-chickpea-salad', 'Tuna and Chickpea Salad', 'No-cook salad of tuna, chickpeas, tomato and cucumber with lemon', 'lunch', 'tuna', '🥗', 10, 'quick', 372, 29, 38, 14, 10, 11, 503, '[{"name":"tuna","amount":100,"unit":"g"},{"name":"chickpeas","amount":100,"unit":"g"},{"name":"tomato","amount":120,"unit":"g"},{"name":"cucumber","amount":80,"unit":"g"},{"name":"onion","amount":20,"unit":"g"},{"name":"olive oil","amount":10,"unit":"g"},{"name":"lemon","amount":1,"unit":"","label":"1 lemon"}]'::jsonb, '["salt","black pepper","handful of fresh parsley"]'::jsonb, '["Drain the tuna and chickpeas","Dice the tomato and cucumber and slice the onion very thinly","Toss everything with the olive oil, the juice of the lemon, salt, pepper and chopped parsley"]'::jsonb, '[]'::jsonb, '["mediterranean","fresh","quick","light","tuna","chickpeas","tomato","cucumber","onion","olive oil","lemon","lunch"]'::jsonb, '["gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 196),
  ('l-lemony-lentil-soup', 'Lemony Lentil Soup', 'Smooth-ish lentil and carrot soup with spinach and lemon', 'lunch', 'lentils', '🍋', 30, 'balanced', 419, 22, 68, 10, 15, 11, 205, '[{"name":"lentils","amount":70,"unit":"g"},{"name":"carrots","amount":60,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"chopped tomatoes","amount":100,"unit":"g"},{"name":"spinach","amount":50,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"},{"name":"olive oil","amount":8,"unit":"g"},{"name":"lemon","amount":1,"unit":"","label":"1 lemon"}]'::jsonb, '["1 tsp ground cumin","1 stock cube","{450} ml water","black pepper"]'::jsonb, '["Dice the onion and carrots and soften them in the olive oil for 5 minutes, then add the chopped garlic and cumin","Add the rinsed lentils, chopped tomatoes, water and stock cube and simmer for 20 minutes until the lentils are soft","Stir in the spinach until wilted","Add the juice of the lemon and black pepper"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","comfort","light","lentils","carrots","onion","chopped tomatoes","spinach","garlic","olive oil","lemon","stovetop","lunch"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 197),
  ('l-chicken-gyros-wrap', 'Chicken Gyros Wrap', 'Oregano chicken in a tortilla with yogurt, cucumber, tomato and onion', 'lunch', 'chicken', '🌯', 15, 'quick', 460, 40, 38, 16, 3, 8, 523, '[{"name":"chicken","amount":130,"unit":"g"},{"name":"tortilla","amount":1,"unit":"","label":"1 tortilla"},{"name":"greek yogurt","amount":50,"unit":"g"},{"name":"cucumber","amount":60,"unit":"g"},{"name":"tomato","amount":60,"unit":"g"},{"name":"onion","amount":20,"unit":"g"},{"name":"olive oil","amount":5,"unit":"g"}]'::jsonb, '["1 tsp dried oregano","1/2 tsp paprika","salt","squeeze of lemon juice"]'::jsonb, '["Cut the chicken into thin strips, toss with the oregano, paprika and salt and fry in the olive oil over high heat for 5 to 6 minutes","Slice the cucumber, tomato and onion","Warm the tortilla, spread it with the yogurt and fill with the chicken and vegetables","Squeeze over lemon juice and roll up"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","quick","light","chicken","tortilla","greek yogurt","cucumber","tomato","onion","olive oil","stovetop","lunch"]'::jsonb, '["nut-allergy","halal"]'::jsonb, 198),
  ('l-salmon-couscous-bowl', 'Salmon Couscous Bowl', 'Flaked salmon over lemon couscous with cucumber, tomato and spinach', 'lunch', 'salmon', '🐟', 15, 'quick', 533, 34, 51, 22, 6, 5, 106, '[{"name":"salmon","amount":120,"unit":"g"},{"name":"couscous","amount":50,"unit":"g"},{"name":"cucumber","amount":80,"unit":"g"},{"name":"tomato","amount":80,"unit":"g"},{"name":"spinach","amount":30,"unit":"g"},{"name":"olive oil","amount":5,"unit":"g"},{"name":"lemon","amount":1,"unit":"","label":"1 lemon"}]'::jsonb, '["{70} ml boiling water","salt","black pepper"]'::jsonb, '["Pour the boiling water over the couscous with a pinch of salt, cover for 5 minutes and fluff with a fork","Fry the salmon in the olive oil over medium heat for 3 to 4 minutes per side and break into flakes","Dice the cucumber and tomato","Serve the couscous on the spinach with the vegetables and salmon, with the juice of the lemon squeezed over"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","fresh","quick","light","salmon","couscous","cucumber","tomato","spinach","olive oil","lemon","stovetop","lunch"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, 199),
  ('l-quinoa-greek-salad', 'Quinoa Greek Salad', 'Quinoa with chickpeas, feta, cucumber, tomato and peppers', 'lunch', 'chickpeas', '🥗', 20, 'quick', 531, 21, 65, 22, 11, 9, 616, '[{"name":"quinoa","amount":60,"unit":"g"},{"name":"chickpeas","amount":60,"unit":"g"},{"name":"feta","amount":40,"unit":"g"},{"name":"cucumber","amount":100,"unit":"g"},{"name":"tomato","amount":120,"unit":"g"},{"name":"peppers","amount":50,"unit":"g"},{"name":"olive oil","amount":8,"unit":"g"}]'::jsonb, '["1 tsp dried oregano","squeeze of lemon juice","salt"]'::jsonb, '["Rinse the quinoa and simmer it in salted water for 12 to 15 minutes, then drain and let it cool a little","Dice the cucumber, tomato and peppers","Toss the quinoa with the vegetables, drained chickpeas, olive oil, oregano and lemon juice","Crumble the feta over the top"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","fresh","quick","light","quinoa","chickpeas","feta","cucumber","tomato","peppers","olive oil","stovetop","lunch"]'::jsonb, '["vegetarian","gluten-free","nut-allergy","halal","kosher"]'::jsonb, 200),
  ('l-spanish-omelette', 'Spanish Potato Omelette', 'Thick omelette of potato and onion cooked in olive oil', 'lunch', 'eggs', '🥔', 30, 'balanced', 520, 25, 42, 28, 5, 5, 249, '[{"name":"eggs","amount":3,"unit":"","label":"3 eggs"},{"name":"potatoes","amount":200,"unit":"g"},{"name":"onion","amount":60,"unit":"g"},{"name":"olive oil","amount":12,"unit":"g"}]'::jsonb, '["salt","black pepper"]'::jsonb, '["Cut the potatoes into thin slices and slice the onion","Cook them gently in the olive oil in a small non-stick pan, covered, for 12 to 15 minutes until soft but not browned","Beat the eggs with salt and pepper, stir in the potatoes and onion, and pour everything back into the pan","Cook over low heat for 5 minutes, flip using a plate and cook 3 more minutes until set"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","light","eggs","potatoes","onion","olive oil","stovetop","lunch"]'::jsonb, '["vegetarian","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 201),
  ('l-garlic-shrimp-couscous', 'Garlic Shrimp with Zucchini Couscous', 'Chili-garlic shrimp over couscous with zucchini and lemon', 'lunch', 'shrimp', '🍤', 15, 'quick', 489, 39, 60, 12, 6, 5, 186, '[{"name":"shrimp","amount":140,"unit":"g"},{"name":"couscous","amount":60,"unit":"g"},{"name":"zucchini","amount":120,"unit":"g"},{"name":"garlic","amount":12,"unit":"g","label":"3 cloves"},{"name":"olive oil","amount":10,"unit":"g"},{"name":"lemon","amount":1,"unit":"","label":"1 lemon"}]'::jsonb, '["1/2 tsp chili flakes","{80} ml boiling water","salt"]'::jsonb, '["Pour the boiling water over the couscous with a pinch of salt, cover for 5 minutes and fluff with a fork","Dice the zucchini and fry it in the olive oil over high heat for 4 minutes","Add the shrimp, sliced garlic and chili flakes and cook for 2 to 3 minutes until the shrimp are pink","Serve over the couscous with the juice of the lemon"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","spicy","quick","light","shrimp","couscous","zucchini","garlic","olive oil","lemon","stovetop","lunch"]'::jsonb, '["dairy-free","nut-allergy","halal"]'::jsonb, 202),
  ('l-beef-kofta-wrap', 'Beef Kofta Wrap', 'Spiced beef kofta in a tortilla with yogurt, cucumber, tomato and lettuce', 'lunch', 'beef mince', '🌯', 20, 'quick', 497, 30, 37, 25, 4, 8, 550, '[{"name":"beef mince","amount":120,"unit":"g"},{"name":"tortilla","amount":1,"unit":"","label":"1 tortilla"},{"name":"yogurt","amount":50,"unit":"g"},{"name":"cucumber","amount":60,"unit":"g"},{"name":"tomato","amount":60,"unit":"g"},{"name":"lettuce","amount":30,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1/2 tsp paprika","1/2 tsp chili flakes","salt"]'::jsonb, '["Mix the beef mince with the cumin, paprika, chili flakes and salt and shape it into {3} short sausages","Fry them in a dry non-stick pan over medium-high heat for 8 minutes, turning, until browned and cooked through","Slice the cucumber and tomato and shred the lettuce","Warm the tortilla, spread with the yogurt, add the kofta and vegetables and roll up"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","spicy","quick","light","beef mince","tortilla","yogurt","cucumber","tomato","lettuce","stovetop","lunch"]'::jsonb, '["nut-allergy","halal"]'::jsonb, 203),
  ('l-mediterranean-tofu-bowl', 'Mediterranean Tofu Couscous Bowl', 'Oregano tofu with zucchini, peppers and tomato over couscous', 'lunch', 'tofu', '🥙', 20, 'quick', 531, 34, 58, 21, 10, 8, 40, '[{"name":"tofu","amount":140,"unit":"g"},{"name":"couscous","amount":55,"unit":"g"},{"name":"zucchini","amount":100,"unit":"g"},{"name":"peppers","amount":80,"unit":"g"},{"name":"tomato","amount":80,"unit":"g"},{"name":"olive oil","amount":8,"unit":"g"}]'::jsonb, '["1 tsp dried oregano","{75} ml boiling water","squeeze of lemon juice","salt"]'::jsonb, '["Pour the boiling water over the couscous with a pinch of salt, cover for 5 minutes and fluff with a fork","Cut the tofu into cubes and fry in the olive oil over medium-high heat for 5 minutes until golden","Add the diced zucchini and peppers with the oregano and cook for 5 minutes","Serve over the couscous with the diced tomato and a squeeze of lemon"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","quick","light","tofu","couscous","zucchini","peppers","tomato","olive oil","stovetop","lunch"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 204),
  ('l-chicken-shawarma-rice-bowl', 'Chicken Shawarma Rice Bowl', 'Spiced chicken over rice with garlic yogurt, cucumber and tomato', 'lunch', 'chicken', '🍗', 25, 'balanced', 663, 46, 76, 18, 2, 6, 99, '[{"name":"chicken","amount":150,"unit":"g"},{"name":"rice","amount":85,"unit":"g"},{"name":"greek yogurt","amount":60,"unit":"g"},{"name":"cucumber","amount":80,"unit":"g"},{"name":"tomato","amount":80,"unit":"g"},{"name":"olive oil","amount":10,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1 tsp paprika","1/2 tsp chili flakes","1/2 tsp ground coriander","salt"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes and drain","Slice the chicken thinly and coat it with the cumin, paprika, chili flakes, coriander and salt","Fry in the olive oil over high heat for 6 minutes until browned at the edges","Serve over the rice with the diced cucumber and tomato and a spoon of yogurt"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","spicy","hearty","chicken","rice","greek yogurt","cucumber","tomato","olive oil","stovetop","lunch"]'::jsonb, '["gluten-free","nut-allergy","halal"]'::jsonb, 205),
  ('l-lentil-feta-salad', 'Lentil and Feta Salad', 'Warm lentils with feta, tomato, cucumber and spinach', 'lunch', 'lentils', '🥗', 30, 'balanced', 462, 26, 54, 18, 10, 6, 498, '[{"name":"lentils","amount":70,"unit":"g"},{"name":"feta","amount":40,"unit":"g"},{"name":"tomato","amount":100,"unit":"g"},{"name":"cucumber","amount":80,"unit":"g"},{"name":"spinach","amount":40,"unit":"g"},{"name":"olive oil","amount":8,"unit":"g"}]'::jsonb, '["splash of red wine vinegar","salt","black pepper"]'::jsonb, '["Simmer the rinsed lentils in unsalted water for 20 to 25 minutes until tender but still holding their shape, then drain","Dice the tomato and cucumber","Toss the warm lentils with the olive oil, vinegar, salt and pepper, then fold in the spinach, tomato and cucumber","Crumble the feta over the top"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","fresh","light","lentils","feta","tomato","cucumber","spinach","olive oil","stovetop","lunch"]'::jsonb, '["vegetarian","gluten-free","nut-allergy","halal","kosher"]'::jsonb, 206),
  ('l-chicken-salad-wrap', 'Chicken Salad Wrap', 'Tortilla with chicken, lettuce, tomato, cucumber and a yogurt dressing', 'lunch', 'chicken', '🌯', 15, 'quick', 379, 35, 37, 10, 4, 7, 522, '[{"name":"chicken","amount":120,"unit":"g"},{"name":"tortilla","amount":1,"unit":"","label":"1 tortilla"},{"name":"lettuce","amount":50,"unit":"g"},{"name":"tomato","amount":60,"unit":"g"},{"name":"cucumber","amount":50,"unit":"g"},{"name":"yogurt","amount":40,"unit":"g"}]'::jsonb, '["1 tsp mustard","salt","black pepper"]'::jsonb, '["Season the chicken and fry it in a non-stick pan over medium heat for 5 to 6 minutes per side, then slice","Stir the mustard and a pinch of salt into the yogurt","Shred the lettuce and slice the tomato and cucumber","Spread the yogurt over the tortilla, add the chicken and vegetables and roll up"]'::jsonb, '["stovetop"]'::jsonb, '["fresh","quick","light","chicken","tortilla","lettuce","tomato","cucumber","yogurt","stovetop","lunch"]'::jsonb, '["nut-allergy","halal"]'::jsonb, 207),
  ('l-egg-salad-sandwich', 'Egg Salad Sandwich', 'Chopped egg in a mustard yogurt dressing with lettuce and cucumber', 'lunch', 'eggs', '🥪', 15, 'quick', 365, 24, 35, 14, 5, 6, 492, '[{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"yogurt","amount":30,"unit":"g"},{"name":"lettuce","amount":30,"unit":"g"},{"name":"cucumber","amount":50,"unit":"g"}]'::jsonb, '["1 tsp mustard","salt","black pepper"]'::jsonb, '["Boil the eggs for 9 minutes, cool them under cold water and peel","Chop the eggs and mix with the yogurt, mustard, salt and pepper","Pile onto one slice of bread with the lettuce and sliced cucumber and top with the second slice"]'::jsonb, '["stovetop"]'::jsonb, '["quick","light","eggs","bread","yogurt","lettuce","cucumber","stovetop","lunch"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, 208),
  ('l-tuna-melt-toastie', 'Tuna Melt Toastie', 'Pan-toasted sandwich with tuna, corn and melted cheese', 'lunch', 'tuna', '🥪', 10, 'quick', 423, 35, 36, 16, 5, 5, 901, '[{"name":"tuna","amount":90,"unit":"g"},{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"cheese","amount":30,"unit":"g"},{"name":"corn","amount":40,"unit":"g"},{"name":"butter","amount":5,"unit":"g"}]'::jsonb, '["black pepper"]'::jsonb, '["Mix the drained tuna with the corn and pepper","Butter one side of each slice of bread and put one slice butter side down in a pan","Top with the tuna and grated cheese and the second slice, butter side up","Toast over medium heat for 2 to 3 minutes per side until golden and the cheese has melted"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","quick","light","tuna","bread","cheese","corn","butter","stovetop","lunch"]'::jsonb, '["nut-allergy","halal","kosher"]'::jsonb, 209),
  ('l-stuffed-sweet-potato-chickpeas', 'Stuffed Sweet Potato with Chickpeas', 'Baked sweet potato filled with spiced chickpeas and spinach', 'lunch', 'chickpeas', '🍠', 15, 'quick', 507, 15, 89, 12, 18, 18, 500, '[{"name":"sweet potato","amount":300,"unit":"g"},{"name":"chickpeas","amount":120,"unit":"g"},{"name":"spinach","amount":50,"unit":"g"},{"name":"olive oil","amount":8,"unit":"g"}]'::jsonb, '["1/2 tsp smoked paprika","1/2 tsp ground cumin","salt","squeeze of lemon juice"]'::jsonb, '["Prick the sweet potato all over and microwave on high for 8 to 10 minutes, turning once, until soft","Warm the drained chickpeas in the olive oil with the paprika, cumin and salt for 3 minutes","Stir in the spinach until it wilts","Split the sweet potato, fill it with the chickpeas and finish with lemon juice"]'::jsonb, '["stovetop","microwave"]'::jsonb, '["comfort","quick","light","sweet potato","chickpeas","spinach","olive oil","stovetop","microwave","lunch"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 210),
  ('l-chicken-vegetable-soup', 'Chicken and Vegetable Soup', 'Clear soup with chicken, potato, carrot and peas', 'lunch', 'chicken', '🍲', 30, 'balanced', 407, 36, 45, 9, 8, 10, 179, '[{"name":"chicken","amount":130,"unit":"g"},{"name":"potatoes","amount":150,"unit":"g"},{"name":"carrots","amount":80,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"peas","amount":50,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 stock cube","{500} ml water","black pepper","handful of fresh parsley"]'::jsonb, '["Dice the onion and soften it in the oil in a pot for 3 minutes","Add the diced potatoes and carrots, the water, stock cube and the whole piece of chicken and simmer for 18 minutes","Lift out the chicken, shred it with two forks and return it to the pot with the peas","Cook 2 more minutes and season with pepper and parsley"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","light","chicken","potatoes","carrots","onion","peas","oil","stovetop","lunch"]'::jsonb, '["gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 211),
  ('l-ham-cheese-spinach-omelette', 'Ham, Cheese and Spinach Omelette', 'Three-egg omelette with ham, cheese and spinach, with toast', 'lunch', 'eggs', '🧀', 10, 'quick', 542, 40, 20, 33, 4, 3, 1029, '[{"name":"eggs","amount":3,"unit":"","label":"3 eggs"},{"name":"ham","amount":40,"unit":"g"},{"name":"cheese","amount":30,"unit":"g"},{"name":"spinach","amount":40,"unit":"g"},{"name":"butter","amount":5,"unit":"g"},{"name":"bread","amount":35,"unit":"g","label":"1 slice"}]'::jsonb, '["black pepper"]'::jsonb, '["Beat the eggs with pepper, cut the ham into strips and grate the cheese","Melt the butter in a non-stick pan, wilt the spinach for 30 seconds and pour in the eggs","When almost set, scatter the ham and cheese over one half and fold over","Cook 1 more minute and serve with the toasted bread"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","quick","light","eggs","ham","cheese","spinach","butter","bread","stovetop","lunch"]'::jsonb, '["nut-allergy"]'::jsonb, 212),
  ('l-warm-salmon-potato-salad', 'Warm Salmon and Potato Salad', 'Flaked salmon with potatoes and green beans in a lemon yogurt dressing', 'lunch', 'salmon', '🥔', 25, 'balanced', 514, 32, 48, 23, 8, 8, 107, '[{"name":"salmon","amount":120,"unit":"g"},{"name":"potatoes","amount":200,"unit":"g"},{"name":"green beans","amount":80,"unit":"g"},{"name":"yogurt","amount":40,"unit":"g"},{"name":"olive oil","amount":5,"unit":"g"},{"name":"lemon","amount":1,"unit":"","label":"1 lemon"}]'::jsonb, '["1 tsp mustard","salt","black pepper"]'::jsonb, '["Boil the potatoes, cut into chunks, in salted water for 15 minutes, adding the green beans for the last 5, then drain","Fry the salmon in the olive oil over medium heat for 3 to 4 minutes per side and break into flakes","Mix the yogurt with the mustard, the juice of the lemon, salt and pepper","Toss the warm potatoes and beans in the dressing and fold in the salmon"]'::jsonb, '["stovetop"]'::jsonb, '["fresh","light","salmon","potatoes","green beans","yogurt","olive oil","lemon","stovetop","lunch"]'::jsonb, '["gluten-free","nut-allergy","halal","kosher"]'::jsonb, 213),
  ('l-turkey-bacon-avocado-sandwich', 'Turkey, Bacon and Avocado Sandwich', 'Toasted sandwich with turkey, crisp bacon, avocado and tomato', 'lunch', 'turkey', '🥪', 15, 'quick', 627, 39, 45, 35, 15, 6, 595, '[{"name":"turkey","amount":100,"unit":"g"},{"name":"bacon","amount":25,"unit":"g"},{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"avocado","amount":1,"unit":"","label":"1 avocado"},{"name":"tomato","amount":60,"unit":"g"},{"name":"lettuce","amount":20,"unit":"g"}]'::jsonb, '["salt","black pepper"]'::jsonb, '["Fry the bacon in a dry pan over medium heat for 4 minutes until crisp and set it aside","Slice the turkey thinly, season and fry it in the bacon fat for 4 minutes until cooked through","Toast the bread and spread it with the mashed avocado","Layer on the turkey, bacon, sliced tomato and lettuce"]'::jsonb, '["stovetop"]'::jsonb, '["quick","turkey","bacon","bread","avocado","tomato","lettuce","stovetop","lunch"]'::jsonb, '["dairy-free","nut-allergy"]'::jsonb, 214),
  ('l-chicken-quinoa-bowl', 'Chicken Quinoa Bowl', 'Quinoa with chicken, broccoli and carrot in a lemon olive oil dressing', 'lunch', 'chicken', '🥗', 20, 'quick', 519, 42, 56, 16, 10, 6, 130, '[{"name":"chicken","amount":130,"unit":"g"},{"name":"quinoa","amount":60,"unit":"g"},{"name":"broccoli","amount":100,"unit":"g"},{"name":"carrots","amount":50,"unit":"g"},{"name":"olive oil","amount":8,"unit":"g"},{"name":"lemon","amount":1,"unit":"","label":"1 lemon"}]'::jsonb, '["salt","black pepper"]'::jsonb, '["Rinse the quinoa and simmer it in salted water for 12 to 15 minutes, adding the broccoli florets for the last 3, then drain","Season the chicken and fry it in half the olive oil for 5 to 6 minutes per side, then slice","Grate the carrots","Serve the quinoa and broccoli topped with the chicken and carrots, dressed with the remaining olive oil and the juice of the lemon"]'::jsonb, '["stovetop"]'::jsonb, '["quick","light","chicken","quinoa","broccoli","carrots","olive oil","lemon","stovetop","lunch"]'::jsonb, '["gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 215),
  ('l-beef-potato-hash', 'Beef and Potato Hash', 'Skillet of beef mince, crisp potatoes, onion and peas', 'lunch', 'beef mince', '🥔', 25, 'balanced', 580, 30, 55, 27, 8, 7, 150, '[{"name":"beef mince","amount":120,"unit":"g"},{"name":"potatoes","amount":250,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"peas","amount":50,"unit":"g"},{"name":"oil","amount":8,"unit":"g"}]'::jsonb, '["1 tsp paprika","salt","black pepper"]'::jsonb, '["Cut the potatoes into 1 cm cubes and fry them in the oil over medium heat for 12 minutes, turning, until golden and tender","Push them aside, add the beef mince and diced onion and brown for 6 minutes","Stir in the peas, paprika, salt and pepper and cook 2 more minutes"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","beef mince","potatoes","onion","peas","oil","stovetop","lunch"]'::jsonb, '["gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 216),
  ('l-pork-schnitzel-sandwich', 'Pork Schnitzel Sandwich', 'Thin breaded pork cutlet in bread with lettuce', 'lunch', 'pork', '🥪', 20, 'quick', 592, 43, 43, 27, 5, 4, 462, '[{"name":"pork","amount":120,"unit":"g"},{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"flour","amount":15,"unit":"g"},{"name":"eggs","amount":1,"unit":"","label":"1 egg"},{"name":"lettuce","amount":30,"unit":"g"},{"name":"oil","amount":12,"unit":"g"}]'::jsonb, '["salt","black pepper","1 tsp mustard","squeeze of lemon juice"]'::jsonb, '["Flatten the pork between two sheets of baking paper until about 1 cm thick and season it","Coat it in the flour, then in the beaten egg, then in the flour again","Fry in the oil over medium-high heat for 3 minutes per side until golden and cooked through","Spread the bread with mustard, add the lettuce and schnitzel and squeeze over lemon juice"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","quick","pork","bread","flour","eggs","lettuce","oil","stovetop","lunch"]'::jsonb, '["dairy-free","nut-allergy"]'::jsonb, 217),
  ('l-tofu-scramble-wrap', 'Tofu Scramble Wrap', 'Tortilla filled with scrambled tofu, spinach, peppers and tomato', 'lunch', 'tofu', '🌯', 15, 'quick', 482, 33, 42, 23, 9, 7, 508, '[{"name":"tofu","amount":150,"unit":"g"},{"name":"tortilla","amount":1,"unit":"","label":"1 tortilla"},{"name":"spinach","amount":50,"unit":"g"},{"name":"peppers","amount":60,"unit":"g"},{"name":"tomato","amount":60,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1/2 tsp turmeric","1/2 tsp ground cumin","salt","black pepper"]'::jsonb, '["Dice the peppers and cook them in the oil for 3 minutes","Crumble in the tofu with the turmeric, cumin, salt and pepper and cook for 5 minutes","Stir in the spinach and diced tomato until the spinach wilts","Warm the tortilla, add the scramble and roll up"]'::jsonb, '["stovetop"]'::jsonb, '["quick","light","tofu","tortilla","spinach","peppers","tomato","oil","stovetop","lunch"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 218),
  ('l-fish-finger-sandwich', 'Crispy Fish Sandwich', 'Pan-fried breaded white fish in bread with lettuce and lemon yogurt', 'lunch', 'white fish', '🐟', 20, 'quick', 554, 43, 44, 22, 5, 5, 489, '[{"name":"white fish","amount":140,"unit":"g"},{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"flour","amount":15,"unit":"g"},{"name":"eggs","amount":1,"unit":"","label":"1 egg"},{"name":"lettuce","amount":30,"unit":"g"},{"name":"yogurt","amount":30,"unit":"g"},{"name":"oil","amount":12,"unit":"g"}]'::jsonb, '["salt","black pepper","squeeze of lemon juice"]'::jsonb, '["Cut the fish into thick strips, season and coat in the flour, then the beaten egg, then the flour again","Fry in the oil over medium-high heat for 2 to 3 minutes per side until golden","Stir lemon juice into the yogurt","Fill the bread with the lettuce, fish and yogurt sauce"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","quick","white fish","bread","flour","eggs","lettuce","yogurt","oil","stovetop","lunch"]'::jsonb, '["nut-allergy","halal","kosher"]'::jsonb, 219),
  ('l-shrimp-avocado-salad', 'Shrimp and Avocado Salad', 'Quick salad of pan-fried shrimp, avocado, tomato and cucumber with lemon', 'lunch', 'shrimp', '🥗', 10, 'quick', 471, 34, 26, 30, 14, 7, 189, '[{"name":"shrimp","amount":140,"unit":"g"},{"name":"avocado","amount":1,"unit":"","label":"1 avocado"},{"name":"lettuce","amount":60,"unit":"g"},{"name":"tomato","amount":100,"unit":"g"},{"name":"cucumber","amount":80,"unit":"g"},{"name":"olive oil","amount":8,"unit":"g"},{"name":"lemon","amount":1,"unit":"","label":"1 lemon"}]'::jsonb, '["salt","black pepper"]'::jsonb, '["Fry the shrimp in half the olive oil over high heat for 2 to 3 minutes until pink and season","Dice the avocado, tomato and cucumber and tear the lettuce","Toss the salad with the remaining olive oil and the juice of the lemon and top with the shrimp"]'::jsonb, '["stovetop"]'::jsonb, '["fresh","quick","light","shrimp","avocado","lettuce","tomato","cucumber","olive oil","lemon","stovetop","lunch"]'::jsonb, '["gluten-free","dairy-free","nut-allergy","halal"]'::jsonb, 220),
  ('l-chicken-burger', 'Chicken Burger', 'Juicy chicken mince patty in bread with cheese, lettuce and tomato', 'lunch', 'chicken mince', '🍔', 15, 'quick', 508, 39, 34, 24, 6, 5, 572, '[{"name":"chicken mince","amount":140,"unit":"g"},{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"lettuce","amount":30,"unit":"g"},{"name":"tomato","amount":60,"unit":"g"},{"name":"cheese","amount":20,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1/2 tsp paprika","salt","black pepper","1 tsp mustard"]'::jsonb, '["Mix the chicken mince with the paprika, salt and pepper and shape into a flat patty","Fry in the oil over medium heat for 5 minutes per side until cooked through, laying the cheese on top for the last minute","Toast the bread and spread with mustard","Add the lettuce, patty and sliced tomato"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","quick","light","chicken mince","bread","lettuce","tomato","cheese","oil","stovetop","lunch"]'::jsonb, '["nut-allergy","halal"]'::jsonb, 221),
  ('l-turkey-vegetable-rice-skillet', 'Turkey and Vegetable Rice Skillet', 'One-pan turkey mince with rice, zucchini and peppers in tomato sauce', 'lunch', 'turkey mince', '🍚', 25, 'balanced', 531, 33, 65, 16, 5, 11, 118, '[{"name":"turkey mince","amount":130,"unit":"g"},{"name":"rice","amount":60,"unit":"g"},{"name":"zucchini","amount":100,"unit":"g"},{"name":"peppers","amount":80,"unit":"g"},{"name":"tomato sauce","amount":100,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 tsp paprika","{200} ml water","salt","black pepper"]'::jsonb, '["Brown the turkey mince in the oil in a lidded pan for 5 minutes","Add the diced zucchini and peppers and the paprika and cook for 3 minutes","Stir in the rice, tomato sauce, water and salt, cover and simmer on low heat for 15 minutes until the rice is tender","Season with pepper"]'::jsonb, '["stovetop"]'::jsonb, '["light","turkey mince","rice","zucchini","peppers","tomato sauce","oil","stovetop","lunch"]'::jsonb, '["gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 222),
  ('l-meatball-sandwich', 'Meatball Sandwich', 'Meatballs in tomato sauce with melted cheese in bread', 'lunch', 'mixed mince', '🥪', 20, 'quick', 541, 34, 38, 28, 6, 7, 572, '[{"name":"mixed mince","amount":110,"unit":"g"},{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"tomato sauce","amount":80,"unit":"g"},{"name":"cheese","amount":20,"unit":"g"}]'::jsonb, '["1/2 tsp dried oregano","salt","black pepper"]'::jsonb, '["Season the mixed mince with the oregano, salt and pepper and roll it into {5} small balls","Fry them in a dry non-stick pan for 6 minutes, turning, until browned","Add the tomato sauce and simmer for 5 minutes until the meatballs are cooked through","Spoon onto the bread, top with the grated cheese and close the sandwich"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","quick","light","mixed mince","bread","tomato sauce","cheese","stovetop","lunch"]'::jsonb, '["nut-allergy"]'::jsonb, 223),
  ('l-egg-potato-green-bean-salad', 'Egg, Potato and Green Bean Salad', 'Warm salad of potatoes, green beans, tomato and boiled eggs', 'lunch', 'eggs', '🥗', 20, 'quick', 445, 20, 46, 21, 8, 7, 178, '[{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"potatoes","amount":200,"unit":"g"},{"name":"green beans","amount":100,"unit":"g"},{"name":"tomato","amount":80,"unit":"g"},{"name":"olive oil","amount":10,"unit":"g"}]'::jsonb, '["1 tsp mustard","splash of vinegar","salt","black pepper"]'::jsonb, '["Boil the potatoes, cut into chunks, for 15 minutes, adding the eggs for the last 8 minutes and the green beans for the last 5","Drain, cool the eggs under cold water, peel and quarter them","Whisk the olive oil with the mustard, vinegar, salt and pepper","Toss the potatoes, beans and tomato wedges in the dressing and top with the eggs"]'::jsonb, '["stovetop"]'::jsonb, '["fresh","quick","light","eggs","potatoes","green beans","tomato","olive oil","stovetop","lunch"]'::jsonb, '["vegetarian","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 224),
  ('l-chicken-bacon-corn-chowder', 'Chicken, Bacon and Corn Chowder', 'Creamy soup with chicken, bacon, potato and corn', 'lunch', 'chicken', '🥣', 30, 'balanced', 495, 37, 46, 18, 5, 13, 438, '[{"name":"chicken","amount":110,"unit":"g"},{"name":"bacon","amount":20,"unit":"g"},{"name":"potatoes","amount":150,"unit":"g"},{"name":"corn","amount":60,"unit":"g"},{"name":"milk","amount":150,"unit":"ml"},{"name":"onion","amount":40,"unit":"g"},{"name":"butter","amount":5,"unit":"g"}]'::jsonb, '["1 stock cube","{250} ml water","black pepper"]'::jsonb, '["Fry the chopped bacon with the butter in a pot for 3 minutes, then add the diced onion for 3 minutes","Add the diced potatoes, the chicken in small pieces, the water and stock cube and simmer for 15 minutes","Stir in the corn and milk and heat gently for 3 minutes without boiling","Lightly crush some of the potatoes to thicken and season with pepper"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","light","chicken","bacon","potatoes","corn","milk","onion","butter","stovetop","lunch"]'::jsonb, '["gluten-free","nut-allergy"]'::jsonb, 225),
  ('l-chicken-avocado-rice-bowl', 'Chicken and Avocado Rice Bowl', 'Rice bowl with sliced chicken, avocado, corn and tomato', 'lunch', 'chicken', '🥑', 20, 'quick', 744, 44, 86, 26, 12, 5, 188, '[{"name":"chicken","amount":150,"unit":"g"},{"name":"rice","amount":80,"unit":"g"},{"name":"avocado","amount":1,"unit":"","label":"1 avocado"},{"name":"corn","amount":50,"unit":"g"},{"name":"tomato","amount":80,"unit":"g"}]'::jsonb, '["squeeze of lime juice","salt","black pepper"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes and drain","Season the chicken and fry it in a non-stick pan over medium heat for 5 to 6 minutes per side, then slice","Dice the avocado and tomato","Top the rice with the chicken, avocado, corn and tomato and squeeze over lime juice"]'::jsonb, '["stovetop"]'::jsonb, '["fresh","quick","hearty","chicken","rice","avocado","corn","tomato","stovetop","lunch"]'::jsonb, '["gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 226),
  ('l-beef-burger-wedges', 'Beef Burger with Potato Wedges', 'Cheeseburger with lettuce and tomato and oven wedges', 'lunch', 'beef mince', '🍔', 35, 'balanced', 807, 46, 68, 39, 9, 7, 597, '[{"name":"beef mince","amount":150,"unit":"g"},{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"potatoes","amount":200,"unit":"g"},{"name":"cheese","amount":20,"unit":"g"},{"name":"lettuce","amount":20,"unit":"g"},{"name":"tomato","amount":50,"unit":"g"},{"name":"oil","amount":8,"unit":"g"}]'::jsonb, '["1/2 tsp paprika","salt","black pepper"]'::jsonb, '["Heat the oven to 220°C, cut the potatoes into wedges, toss with the oil, paprika and salt and roast for 25 minutes, turning once","Season the beef mince, shape it into a patty and fry in a dry pan over medium-high heat for 4 minutes per side","Lay the cheese on the patty for the last minute so it melts","Serve in the bread with the lettuce and sliced tomato, with the wedges on the side"]'::jsonb, '["stovetop","oven"]'::jsonb, '["comfort","hearty","beef mince","bread","potatoes","cheese","lettuce","tomato","oil","stovetop","oven","lunch"]'::jsonb, '["nut-allergy","halal"]'::jsonb, 227),
  ('l-steak-sandwich', 'Steak and Onion Sandwich', 'Seared beef with soft onions and cheese in toasted bread', 'lunch', 'beef', '🥩', 15, 'quick', 534, 47, 37, 22, 6, 6, 657, '[{"name":"beef","amount":140,"unit":"g"},{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"onion","amount":60,"unit":"g"},{"name":"cheese","amount":25,"unit":"g"},{"name":"butter","amount":8,"unit":"g"},{"name":"lettuce","amount":20,"unit":"g"}]'::jsonb, '["1 tsp mustard","salt","black pepper"]'::jsonb, '["Slice the onion and cook it in the butter over medium heat for 6 minutes until soft and golden, then push aside","Season the beef and sear it in the same pan over high heat for 2 minutes per side, rest for 2 minutes and slice thinly","Toast the bread and spread with mustard","Fill with the lettuce, beef, onions and sliced cheese"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","quick","light","beef","bread","onion","cheese","butter","lettuce","stovetop","lunch"]'::jsonb, '["nut-allergy","halal"]'::jsonb, 228),
  ('l-pork-apple-salad', 'Pork and Apple Salad', 'Pan-fried pork strips over lettuce with apple, cucumber and a mustard dressing', 'lunch', 'pork', '🍏', 15, 'quick', 478, 34, 45, 19, 8, 22, 235, '[{"name":"pork","amount":130,"unit":"g"},{"name":"apple","amount":1,"unit":"","label":"1 apple"},{"name":"lettuce","amount":60,"unit":"g"},{"name":"cucumber","amount":80,"unit":"g"},{"name":"olive oil","amount":10,"unit":"g"},{"name":"bread","amount":35,"unit":"g","label":"1 slice"}]'::jsonb, '["1 tsp mustard","splash of vinegar","salt","black pepper"]'::jsonb, '["Cut the pork into thin strips, season and fry in half the olive oil over high heat for 4 to 5 minutes","Slice the apple and cucumber thinly and tear the lettuce","Whisk the remaining olive oil with the mustard, vinegar, salt and pepper","Toss the salad in the dressing, top with the pork and serve with the bread"]'::jsonb, '["stovetop"]'::jsonb, '["fresh","quick","light","pork","apple","lettuce","cucumber","olive oil","bread","stovetop","lunch"]'::jsonb, '["dairy-free","nut-allergy"]'::jsonb, 229),
  ('l-chicken-pesto-panini', 'Chicken Pesto Panini', 'Pressed sandwich with chicken, mozzarella, tomato and pesto', 'lunch', 'chicken', '🥪', 20, 'quick', 745, 62, 51, 32, 8, 7, 1090, '[{"name":"chicken","amount":150,"unit":"g"},{"name":"bread","amount":105,"unit":"g","label":"3 slices"},{"name":"mozzarella","amount":60,"unit":"g"},{"name":"pesto","amount":25,"unit":"g"},{"name":"tomato","amount":80,"unit":"g"}]'::jsonb, '["salt","black pepper"]'::jsonb, '["Season the chicken and fry it in a non-stick pan over medium heat for 5 to 6 minutes per side, then slice","Spread the pesto on the bread and layer on the chicken, sliced mozzarella and sliced tomato to make a double-decker sandwich","Toast it in the dry pan over medium heat, pressing down with a spatula, for 2 to 3 minutes per side until the cheese melts"]'::jsonb, '["stovetop"]'::jsonb, '["italian","quick","hearty","chicken","bread","mozzarella","pesto","tomato","stovetop","lunch"]'::jsonb, '["halal"]'::jsonb, 230),
  ('l-beef-bean-burrito', 'Beef and Bean Lunch Burritos', 'Two burritos with spiced beef mince, kidney beans and cheese', 'lunch', 'beef mince', '🌯', 20, 'quick', 825, 46, 75, 37, 8, 9, 1281, '[{"name":"beef mince","amount":140,"unit":"g"},{"name":"tortilla","amount":2,"unit":"","label":"2 tortillas"},{"name":"kidney beans","amount":60,"unit":"g"},{"name":"cheese","amount":20,"unit":"g"},{"name":"tomato","amount":60,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1 tsp paprika","salt"]'::jsonb, '["Brown the beef mince in a dry pan over high heat for 6 minutes","Add the cumin, paprika, salt, drained kidney beans and a splash of water and cook for 2 minutes","Warm the tortillas in a dry pan","Fill them with the beef and beans, grated cheese and diced tomato, fold in the sides and roll up"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","quick","hearty","beef mince","tortilla","kidney beans","cheese","tomato","stovetop","lunch"]'::jsonb, '["nut-allergy","halal"]'::jsonb, 231),
  ('l-salmon-avocado-rice-bowl', 'Salmon and Avocado Rice Bowl', 'Pan-fried salmon over rice with avocado, cucumber and soy', 'lunch', 'salmon', '🍣', 20, 'quick', 825, 38, 79, 40, 11, 2, 647, '[{"name":"salmon","amount":140,"unit":"g"},{"name":"rice","amount":80,"unit":"g"},{"name":"avocado","amount":1,"unit":"","label":"1 avocado"},{"name":"cucumber","amount":80,"unit":"g"},{"name":"soy sauce","amount":10,"unit":"g"}]'::jsonb, '["squeeze of lime juice","sesame seeds if you have them"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes and drain","Fry the salmon in a non-stick pan over medium heat for 3 to 4 minutes per side and break into large flakes","Slice the avocado and cucumber","Top the rice with the salmon, avocado and cucumber and dress with the soy sauce and lime juice"]'::jsonb, '["stovetop"]'::jsonb, '["asian","fresh","quick","hearty","salmon","rice","avocado","cucumber","soy sauce","stovetop","lunch"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, 232),
  ('l-peanut-chicken-noodles', 'Peanut Chicken Noodles', 'Warm noodles with chicken and carrot in a peanut soy sauce', 'lunch', 'chicken', '🥜', 20, 'quick', 752, 54, 76, 26, 6, 7, 1058, '[{"name":"chicken","amount":150,"unit":"g"},{"name":"noodles","amount":90,"unit":"g"},{"name":"peanut butter","amount":25,"unit":"g"},{"name":"carrots","amount":60,"unit":"g"},{"name":"soy sauce","amount":15,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["3 tbsp hot water","squeeze of lime juice"]'::jsonb, '["Cook the noodles according to the packet and drain","Slice the chicken and stir-fry it in the oil over high heat for 5 minutes with the carrots cut into thin strips","Whisk the peanut butter with the soy sauce, hot water and lime juice","Toss the noodles and sauce through the chicken and heat for 1 minute"]'::jsonb, '["stovetop"]'::jsonb, '["asian","quick","hearty","chicken","noodles","peanut butter","carrots","soy sauce","oil","stovetop","lunch"]'::jsonb, '["dairy-free","halal","kosher"]'::jsonb, 233),
  ('l-tuna-pesto-pasta', 'Tuna Pesto Pasta', 'Pasta with tuna, peas and pesto', 'lunch', 'tuna', '🍝', 15, 'quick', 667, 42, 88, 16, 7, 6, 667, '[{"name":"tuna","amount":120,"unit":"g"},{"name":"pasta","amount":105,"unit":"g"},{"name":"pesto","amount":30,"unit":"g"},{"name":"peas","amount":60,"unit":"g"}]'::jsonb, '["black pepper","squeeze of lemon juice"]'::jsonb, '["Cook the pasta in salted boiling water according to the packet, adding the peas for the last 2 minutes, then drain","Toss with the pesto and the drained tuna","Season with pepper and lemon juice"]'::jsonb, '["stovetop"]'::jsonb, '["italian","quick","hearty","tuna","pasta","pesto","peas","stovetop","lunch"]'::jsonb, '["halal","kosher"]'::jsonb, 234),
  ('l-beef-egg-fried-rice', 'Beef and Egg Fried Rice', 'Fried rice with beef strips, scrambled egg and peas', 'lunch', 'beef', '🍚', 20, 'quick', 791, 53, 80, 27, 4, 3, 1111, '[{"name":"beef","amount":130,"unit":"g"},{"name":"rice","amount":90,"unit":"g"},{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"peas","amount":50,"unit":"g"},{"name":"soy sauce","amount":15,"unit":"g"},{"name":"oil","amount":10,"unit":"g"}]'::jsonb, '["black pepper","1 tsp grated ginger"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes, drain and let it steam dry","Slice the beef thinly and sear it in the oil over very high heat for 2 minutes with the ginger","Push it aside, scramble the eggs in the gap, then add the peas","Add the rice and soy sauce and stir-fry for 2 minutes"]'::jsonb, '["stovetop"]'::jsonb, '["asian","quick","hearty","beef","rice","eggs","peas","soy sauce","oil","stovetop","lunch"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, 235),
  ('l-chicken-feta-chickpea-couscous', 'Chicken, Feta and Chickpea Couscous', 'Couscous with oregano chicken, chickpeas, cucumber and feta', 'lunch', 'chicken', '🥙', 20, 'quick', 798, 56, 84, 25, 10, 5, 730, '[{"name":"chicken","amount":150,"unit":"g"},{"name":"couscous","amount":80,"unit":"g"},{"name":"chickpeas","amount":80,"unit":"g"},{"name":"feta","amount":40,"unit":"g"},{"name":"cucumber","amount":80,"unit":"g"},{"name":"olive oil","amount":10,"unit":"g"}]'::jsonb, '["{100} ml boiling water","1 tsp dried oregano","salt","squeeze of lemon juice"]'::jsonb, '["Pour the boiling water over the couscous with a pinch of salt, cover for 5 minutes and fluff with a fork","Season the chicken with the oregano and salt and fry in half the olive oil for 5 to 6 minutes per side, then slice","Mix the couscous with the drained chickpeas, diced cucumber, remaining olive oil and lemon juice","Top with the chicken and crumbled feta"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","quick","hearty","chicken","couscous","chickpeas","feta","cucumber","olive oil","stovetop","lunch"]'::jsonb, '["nut-allergy","halal"]'::jsonb, 236),
  ('l-tofu-peanut-rice-bowl', 'Tofu Peanut Rice Bowl', 'Golden tofu over rice with carrot, cucumber and a peanut soy sauce', 'lunch', 'tofu', '🥜', 20, 'quick', 832, 48, 88, 36, 9, 7, 841, '[{"name":"tofu","amount":200,"unit":"g"},{"name":"rice","amount":85,"unit":"g"},{"name":"peanut butter","amount":25,"unit":"g"},{"name":"carrots","amount":60,"unit":"g"},{"name":"cucumber","amount":60,"unit":"g"},{"name":"soy sauce","amount":12,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["3 tbsp hot water","squeeze of lime juice"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes and drain","Cut the tofu into cubes and fry in the oil over medium-high heat for 6 minutes until golden","Whisk the peanut butter with the soy sauce, hot water and lime juice","Serve the tofu over the rice with the grated carrots and sliced cucumber and pour over the sauce"]'::jsonb, '["stovetop"]'::jsonb, '["asian","quick","hearty","tofu","rice","peanut butter","carrots","cucumber","soy sauce","oil","stovetop","lunch"]'::jsonb, '["vegetarian","vegan","dairy-free","halal","kosher"]'::jsonb, 237),
  ('l-lentil-chickpea-power-bowl', 'Lentil and Chickpea Power Bowl', 'Warm lentils and chickpeas with avocado and tomato', 'lunch', 'lentils', '🥑', 30, 'balanced', 735, 32, 94, 30, 27, 10, 315, '[{"name":"lentils","amount":80,"unit":"g"},{"name":"chickpeas","amount":120,"unit":"g"},{"name":"avocado","amount":1,"unit":"","label":"1 avocado"},{"name":"tomato","amount":100,"unit":"g"},{"name":"olive oil","amount":5,"unit":"g"}]'::jsonb, '["splash of red wine vinegar","1/2 tsp ground cumin","salt","black pepper"]'::jsonb, '["Simmer the rinsed lentils in unsalted water for 20 to 25 minutes until tender, adding the drained chickpeas for the last 2 minutes, then drain","Toss with the olive oil, vinegar, cumin, salt and pepper","Dice the tomato and avocado and fold them through"]'::jsonb, '["stovetop"]'::jsonb, '["fresh","hearty","lentils","chickpeas","avocado","tomato","olive oil","stovetop","lunch"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 238),
  ('l-turkey-cheese-quesadilla', 'Turkey and Cheese Quesadilla', 'Crisp tortillas with turkey, peppers and melted cheese', 'lunch', 'turkey', '🧀', 20, 'quick', 765, 56, 64, 32, 5, 8, 1399, '[{"name":"turkey","amount":140,"unit":"g"},{"name":"tortilla","amount":2,"unit":"","label":"2 tortillas"},{"name":"cheese","amount":50,"unit":"g"},{"name":"peppers","amount":60,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 tsp paprika","1/2 tsp ground cumin","salt"]'::jsonb, '["Slice the turkey thinly, season with the paprika, cumin and salt and fry in the oil with the diced peppers for 6 minutes","Cover one tortilla with half the grated cheese, the turkey and peppers and the rest of the cheese, and top with the second tortilla","Cook in a clean dry pan over medium heat for 3 minutes per side until golden","Cut into wedges"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","quick","hearty","turkey","tortilla","cheese","peppers","oil","stovetop","lunch"]'::jsonb, '["nut-allergy","halal"]'::jsonb, 239),
  ('l-bacon-egg-potato-hash', 'Bacon, Egg and Potato Hash', 'Crisp potatoes with bacon and onion, topped with three fried eggs', 'lunch', 'eggs', '🥓', 25, 'balanced', 724, 34, 57, 40, 7, 5, 629, '[{"name":"eggs","amount":3,"unit":"","label":"3 eggs"},{"name":"potatoes","amount":300,"unit":"g"},{"name":"bacon","amount":50,"unit":"g"},{"name":"onion","amount":40,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1/2 tsp paprika","black pepper"]'::jsonb, '["Cut the potatoes into 1 cm cubes and fry them in the oil over medium heat for 12 minutes until golden","Add the chopped bacon and diced onion with the paprika and cook for 5 minutes until the bacon is crisp","Make {n:eggs} gaps in the hash, crack in the eggs, cover and cook for 3 minutes until the whites are set","Season with pepper"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","hearty","eggs","potatoes","bacon","onion","oil","stovetop","lunch"]'::jsonb, '["gluten-free","dairy-free","nut-allergy"]'::jsonb, 240),
  ('l-creamy-garlic-shrimp-pasta', 'Creamy Garlic Shrimp Pasta', 'Pasta with shrimp and spinach in a garlic parmesan cream sauce', 'lunch', 'shrimp', '🍤', 15, 'quick', 733, 54, 80, 22, 4, 6, 471, '[{"name":"shrimp","amount":160,"unit":"g"},{"name":"pasta","amount":95,"unit":"g"},{"name":"cream sauce","amount":80,"unit":"g"},{"name":"garlic","amount":12,"unit":"g","label":"3 cloves"},{"name":"parmesan","amount":15,"unit":"g"},{"name":"spinach","amount":50,"unit":"g"}]'::jsonb, '["black pepper","squeeze of lemon juice"]'::jsonb, '["Cook the pasta in salted boiling water according to the packet and drain, keeping a little of the water","Fry the shrimp in a non-stick pan over high heat for 2 minutes with the sliced garlic","Add the cream sauce, spinach and a splash of pasta water and simmer for 2 minutes","Toss in the pasta and grated parmesan and finish with pepper and lemon juice"]'::jsonb, '["stovetop"]'::jsonb, '["italian","comfort","quick","hearty","shrimp","pasta","cream sauce","garlic","parmesan","spinach","stovetop","lunch"]'::jsonb, '["nut-allergy","halal"]'::jsonb, 241),
  ('l-chicken-meatball-sub', 'Chicken Meatball Sub', 'Chicken meatballs in tomato sauce with melted mozzarella in bread', 'lunch', 'chicken mince', '🥖', 25, 'balanced', 681, 54, 55, 28, 8, 9, 845, '[{"name":"chicken mince","amount":160,"unit":"g"},{"name":"bread","amount":105,"unit":"g","label":"3 slices"},{"name":"tomato sauce","amount":100,"unit":"g"},{"name":"mozzarella","amount":50,"unit":"g"}]'::jsonb, '["1/2 tsp dried oregano","salt","black pepper"]'::jsonb, '["Season the chicken mince with the oregano, salt and pepper and roll it into {6} balls","Brown them in a non-stick pan for 6 minutes, turning","Add the tomato sauce, cover and simmer for 6 minutes until cooked through","Pile the meatballs and sauce onto the bread, top with the sliced mozzarella and let it melt for a minute before closing the sandwich"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","hearty","chicken mince","bread","tomato sauce","mozzarella","stovetop","lunch"]'::jsonb, '["nut-allergy","halal"]'::jsonb, 242),
  ('l-tofu-lentil-salad', 'Warm Tofu and Lentil Salad', 'Golden tofu over lentils with tomato, cucumber and a lemon dressing', 'lunch', 'tofu', '🥗', 25, 'balanced', 496, 40, 43, 22, 11, 5, 31, '[{"name":"tofu","amount":150,"unit":"g"},{"name":"lentils","amount":50,"unit":"g"},{"name":"tomato","amount":100,"unit":"g"},{"name":"cucumber","amount":100,"unit":"g"},{"name":"olive oil","amount":8,"unit":"g"}]'::jsonb, '["1 tbsp lemon juice","pinch of dried oregano","pinch of salt","black pepper"]'::jsonb, '["Rinse the lentils and simmer them in {300} ml of salted water for 18 to 20 minutes until tender, then drain","Pat the tofu dry, cut it into cubes and fry it in half of the olive oil over medium-high heat for 6 to 8 minutes until golden","Dice the tomato and the cucumber and toss them with the lentils, the rest of the olive oil, the lemon juice, oregano, salt and black pepper","Top the salad with the warm tofu"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","fresh","light","tofu","lentils","tomato","cucumber","olive oil","stovetop","lunch"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 243),
  ('l-chickpea-tofu-spinach-bowl', 'Chickpea and Tofu Spinach Bowl', 'Chickpeas and crumbled tofu fried with spinach, tomato and smoked paprika', 'lunch', 'chickpeas', '🥘', 15, 'quick', 548, 45, 46, 25, 17, 9, 462, '[{"name":"chickpeas","amount":150,"unit":"g"},{"name":"tofu","amount":180,"unit":"g"},{"name":"spinach","amount":80,"unit":"g"},{"name":"tomato","amount":100,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 tsp smoked paprika","pinch of cumin","pinch of salt","black pepper"]'::jsonb, '["Drain and rinse the chickpeas, crumble the tofu and dice the tomato","Heat the oil in a pan over medium-high heat and fry the tofu and the chickpeas with the smoked paprika, cumin and salt for 6 minutes until they start to colour","Add the tomato and the spinach and cook for 2 minutes until the spinach has wilted","Season with black pepper and serve in a bowl"]'::jsonb, '["stovetop"]'::jsonb, '["quick","light","chickpeas","tofu","spinach","tomato","oil","stovetop","lunch"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 244),
  ('l-teriyaki-tofu-pea-rice-bowl', 'Teriyaki Tofu Rice Bowl', 'Seared tofu glazed with teriyaki over rice with peas and carrot', 'lunch', 'tofu', '🍚', 20, 'quick', 644, 49, 64, 25, 12, 13, 1346, '[{"name":"tofu","amount":220,"unit":"g"},{"name":"rice","amount":40,"unit":"g"},{"name":"peas","amount":100,"unit":"g"},{"name":"carrots","amount":80,"unit":"g"},{"name":"teriyaki","amount":25,"unit":"ml"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '[]'::jsonb, '["Cook the rice in {100} ml of salted water, covered, for 12 minutes, then leave it to steam off the heat","Pat the tofu dry and cut it into cubes; slice the carrots thinly","Heat the oil in a pan over medium-high heat and fry the tofu for 6 minutes until golden, then add the carrots and the peas and cook for 3 minutes","Pour in the teriyaki, toss for 1 minute until glossy, and serve over the rice"]'::jsonb, '["stovetop"]'::jsonb, '["asian","quick","tofu","rice","peas","carrots","teriyaki","oil","stovetop","lunch"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 245),
  ('l-bean-tofu-burrito-bowl', 'Bean and Tofu Burrito Bowl', 'Kidney beans and spiced tofu with corn, peppers and fresh tomato, no rice', 'lunch', 'kidney beans', '🌶️', 15, 'quick', 565, 46, 54, 23, 16, 14, 502, '[{"name":"kidney beans","amount":150,"unit":"g"},{"name":"tofu","amount":180,"unit":"g"},{"name":"corn","amount":60,"unit":"g"},{"name":"peppers","amount":80,"unit":"g"},{"name":"tomato","amount":80,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 tsp cumin","1 tsp smoked paprika","pinch of salt","squeeze of lime or lemon juice"]'::jsonb, '["Drain and rinse the beans and the corn; dice the peppers and the tomato and crumble the tofu into chunks","Heat the oil in a pan over medium-high heat and fry the tofu with the cumin, smoked paprika and salt for 5 minutes","Add the peppers, the beans and the corn and cook for 4 minutes until hot","Serve in a bowl with the tomato on top and a squeeze of lime or lemon juice"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","quick","kidney beans","tofu","corn","peppers","tomato","oil","stovetop","lunch"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 246),
  ('l-lentil-tofu-vegetable-soup', 'Lentil and Tofu Vegetable Soup', 'A thick tomato and lentil soup with carrot, spinach and cubes of tofu', 'lunch', 'lentils', '🍲', 30, 'balanced', 566, 45, 63, 19, 17, 11, 302, '[{"name":"lentils","amount":60,"unit":"g"},{"name":"tofu","amount":150,"unit":"g"},{"name":"carrots","amount":80,"unit":"g"},{"name":"onion","amount":60,"unit":"g"},{"name":"spinach","amount":60,"unit":"g"},{"name":"chopped tomatoes","amount":150,"unit":"g"},{"name":"olive oil","amount":5,"unit":"g"}]'::jsonb, '["1 tsp cumin","pinch of salt","black pepper"]'::jsonb, '["Dice the onion and the carrots and soften them in the olive oil in a pot over medium heat for 4 minutes","Add the rinsed lentils, the chopped tomatoes, the cumin and {450} ml of water, bring to the boil and simmer for 18 minutes","Cut the tofu into small cubes and add it with the spinach; simmer for 3 more minutes","Season with salt and black pepper and serve"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","lentils","tofu","carrots","onion","spinach","chopped tomatoes","olive oil","stovetop","lunch"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 247),
  ('l-tofu-pea-quinoa-stir-fry', 'Tofu and Pea Quinoa Stir-Fry', 'Quinoa stir-fried with golden tofu, peas, peppers and soy sauce', 'lunch', 'tofu', '🥢', 20, 'quick', 590, 47, 49, 27, 13, 8, 1129, '[{"name":"tofu","amount":200,"unit":"g"},{"name":"quinoa","amount":40,"unit":"g"},{"name":"peas","amount":100,"unit":"g"},{"name":"peppers","amount":60,"unit":"g"},{"name":"soy sauce","amount":15,"unit":"ml"},{"name":"oil","amount":6,"unit":"g"}]'::jsonb, '[]'::jsonb, '["Rinse the quinoa and simmer it in {100} ml of water, covered, for 12 minutes, then fluff it with a fork","Pat the tofu dry and cut it into cubes; dice the peppers","Heat the oil in a pan over high heat and fry the tofu for 6 minutes until golden, then add the peppers and the peas and cook for 2 minutes","Add the quinoa and the soy sauce, toss for 1 minute and serve"]'::jsonb, '["stovetop"]'::jsonb, '["asian","quick","tofu","quinoa","peas","peppers","soy sauce","oil","stovetop","lunch"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 248),
  ('s-peanut-butter-banana-toast', 'Peanut Butter Banana Toast', 'Toast spread with peanut butter and topped with sliced banana', 'snack', 'bread', '🍌', 5, 'quick', 315, 10, 47, 12, 6, 18, 246, '[{"name":"bread","amount":35,"unit":"g","label":"1 slice"},{"name":"peanut butter","amount":20,"unit":"g"},{"name":"banana","amount":1,"unit":"","label":"1 banana"}]'::jsonb, '["pinch of cinnamon"]'::jsonb, '["Toast the bread until golden","Spread the peanut butter over the toast","Slice the banana, lay it on top and finish with a little cinnamon"]'::jsonb, '[]'::jsonb, '["comfort","quick","bread","peanut butter","banana","snack"]'::jsonb, '["vegetarian","vegan","dairy-free","halal","kosher"]'::jsonb, 249),
  ('s-apple-peanut-butter', 'Apple Slices with Peanut Butter', 'Crisp apple wedges with peanut butter for dipping', 'snack', 'apple', '🍎', 5, 'quick', 243, 6, 30, 13, 6, 21, 108, '[{"name":"apple","amount":1,"unit":"","label":"1 apple"},{"name":"peanut butter","amount":25,"unit":"g"}]'::jsonb, '[]'::jsonb, '["Core the apple and cut it into wedges","Put the peanut butter in a small bowl and dip the wedges as you eat"]'::jsonb, '[]'::jsonb, '["fresh","quick","apple","peanut butter","snack"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","halal","kosher"]'::jsonb, 250),
  ('s-hummus-carrot-sticks', 'Quick Hummus with Carrot Sticks', 'Chickpeas mashed with olive oil, garlic and lemon, with carrot sticks to dip', 'snack', 'chickpeas', '🥕', 10, 'quick', 295, 9, 38, 13, 11, 11, 350, '[{"name":"chickpeas","amount":100,"unit":"g"},{"name":"olive oil","amount":10,"unit":"g"},{"name":"garlic","amount":4,"unit":"g","label":"1 clove"},{"name":"carrots","amount":150,"unit":"g"}]'::jsonb, '["squeeze of lemon juice","pinch of salt","pinch of paprika"]'::jsonb, '["Drain and rinse the chickpeas, then mash them with a fork or blend them with the olive oil, the crushed garlic, a squeeze of lemon juice, a pinch of salt and a spoon of water until smooth","Peel the carrots and cut them into sticks","Serve the hummus with a pinch of paprika on top and the carrot sticks on the side"]'::jsonb, '[]'::jsonb, '["mediterranean","fresh","quick","chickpeas","olive oil","garlic","carrots","snack"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 251),
