  ('s-cottage-cheese-tomato-toast', 'Cottage Cheese and Tomato Toast', 'Toast with cottage cheese, sliced tomato and a thread of olive oil', 'snack', 'cottage cheese', '🍅', 5, 'quick', 245, 16, 21, 11, 3, 6, 478, '[{"name":"bread","amount":35,"unit":"g","label":"1 slice"},{"name":"cottage cheese","amount":100,"unit":"g"},{"name":"tomato","amount":80,"unit":"g"},{"name":"olive oil","amount":5,"unit":"g"}]'::jsonb, '["pinch of salt","black pepper"]'::jsonb, '["Toast the bread","Pile the cottage cheese on the toast and lay the sliced tomato on top","Drizzle with the olive oil and season with salt and black pepper"]'::jsonb, '[]'::jsonb, '["fresh","quick","bread","cottage cheese","tomato","olive oil","snack"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, 253),
  ('s-avocado-toast', 'Avocado Toast', 'Two slices of toast with mashed avocado and tomato', 'snack', 'avocado', '🥑', 5, 'quick', 297, 11, 38, 13, 9, 5, 326, '[{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"avocado","amount":70,"unit":"g"},{"name":"tomato","amount":50,"unit":"g"}]'::jsonb, '["squeeze of lemon juice","pinch of salt","black pepper"]'::jsonb, '["Toast the bread","Mash the avocado with a squeeze of lemon juice and a pinch of salt, and spread it over the toast","Top with the diced tomato and a little black pepper"]'::jsonb, '[]'::jsonb, '["fresh","quick","bread","avocado","tomato","snack"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 254),
  ('s-boiled-eggs-cucumber-toast', 'Boiled Eggs with Cucumber and Toast', 'Soft-boiled eggs with cucumber slices and a slice of toast', 'snack', 'eggs', '🥚', 12, 'quick', 261, 19, 19, 12, 3, 4, 317, '[{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"cucumber","amount":100,"unit":"g"},{"name":"bread","amount":35,"unit":"g","label":"1 slice"}]'::jsonb, '["pinch of salt","black pepper"]'::jsonb, '["Boil the eggs for 7 minutes, cool them under cold water and peel them","Toast the bread and slice the cucumber","Halve the eggs, season with salt and black pepper, and serve with the cucumber and the toast"]'::jsonb, '["stovetop"]'::jsonb, '["quick","eggs","cucumber","bread","stovetop","snack"]'::jsonb, '["vegetarian","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 255),
  ('s-banana-oat-bites', 'No-Bake Banana Oat Bites', 'Oats, mashed banana and peanut butter rolled into small bites', 'snack', 'oats', '🍪', 10, 'quick', 310, 9, 51, 10, 7, 17, 67, '[{"name":"oats","amount":30,"unit":"g"},{"name":"peanut butter","amount":15,"unit":"g"},{"name":"banana","amount":1,"unit":"","label":"1 banana"}]'::jsonb, '["pinch of cinnamon"]'::jsonb, '["Mash the banana in a bowl with a fork","Stir in the oats, the peanut butter and a pinch of cinnamon until the mixture holds together","Roll into {6} small balls; eat them straight away or chill them for 15 minutes to firm up"]'::jsonb, '[]'::jsonb, '["comfort","quick","oats","peanut butter","banana","snack"]'::jsonb, '["vegetarian","vegan","dairy-free","halal","kosher"]'::jsonb, 256),
  ('s-roasted-chickpeas', 'Crispy Roasted Chickpeas', 'Chickpeas roasted with olive oil and smoked paprika until crunchy', 'snack', 'chickpeas', '🫘', 30, 'quick', 279, 11, 34, 12, 10, 6, 369, '[{"name":"chickpeas","amount":150,"unit":"g"},{"name":"olive oil","amount":8,"unit":"g"}]'::jsonb, '["1 tsp smoked paprika","pinch of salt"]'::jsonb, '["Heat the oven to 200°C. Drain and rinse the chickpeas and pat them completely dry","Toss them with the olive oil, the smoked paprika and a pinch of salt and spread them on a baking tray","Roast for 20 to 25 minutes, shaking the tray once, until crisp"]'::jsonb, '["oven"]'::jsonb, '["chickpeas","olive oil","oven","snack"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 257),
